import type { HiCommentaryFragment } from './_types';

export const bhagavadgitaHi: HiCommentaryFragment = {
  '1:1': {
    explanation: `धृतराष्ट्र का प्रश्न — "धर्मक्षेत्रे कुरुक्षेत्रे..." — केवल युद्धभूमि का वर्णन नहीं है, बल्कि एक गहन मनोवैज्ञानिक संकेत है। "ममकाः" (मेरे पुत्र) और "पाण्डवाः" का विभाजन — धृतराष्ट्र अपने पुत्रों को "मेरे" कहते हैं, पाण्डवों को केवल "पाण्डव"। यही "ममता" (स्वामित्व-भाव) संपूर्ण महाभारत-युद्ध का मूल कारण है। धृतराष्ट्र का अंधापन केवल शारीरिक नहीं — वह नैतिक अंधत्व है, आसक्ति-जनित अंधत्व। वह जानते हैं कि पाण्डवों का अधिकार उचित है, पर ममता उन्हें अधर्म को अंधानुमोदन करने पर मजबूर करती है। गीता का आरंभ ही इस मूलभूत मानवीय दोष — आसक्ति-जनित अंधत्व — से होता है, और संपूर्ण गीता इसी आसक्ति के विश्लेषण और उससे मुक्ति का उपदेश है।`,
    science: `आधुनिक संज्ञानात्मक विज्ञान इस पक्षपात की पुष्टि करता है: "अपने-समूह के प्रति झुकाव" (in-group favoritism) मानसिक अंध-बिंदु पैदा करता है। मस्तिष्क का एमिग्डाला "अपनों" बनाम "परायों" के प्रति भिन्न-भिन्न भावनात्मक प्रतिक्रिया देता है — यही वह तंत्र है जो समाजों को संघर्ष की ओर ले जाता है।`,
    lifeLesson: `"मेरा-तेरा" जैसे स्वामित्व-सूचक शब्दों से सावधान रहो। हर युद्ध — व्यक्तिगत हो या वैश्विक — "मैं बनाम वे" से आरंभ होता है। अपनी आसक्तियों का आत्म-निरीक्षण ही स्पष्टता की ओर पहला कदम है।`,
  },
  '1:20': {
    explanation: `अर्जुन को "कपिध्वज" — हनुमान-ध्वज वाला — कहा गया है। उसके रथ के ध्वज पर हनुमान का प्रतीक है, जो असीम शक्ति, भक्ति और निस्वार्थ सेवा का प्रतीक है। यह दिव्य संरक्षण का संकेत है — अर्जुन अकेला नहीं, उसके पीछे एक दिव्य शक्ति सक्रिय है। धनुष उठाना उसकी प्रारंभिक तत्परता दिखाता है — यहाँ अर्जुन अभी योद्धा है, विषादग्रस्त नहीं। यही तत्परता कुछ ही क्षणों में विषाद में बदल जाएगी, और वहीं से गीता का उपदेश आरंभ होगा।`,
    science: `मनोविज्ञान में Symbolic Self-Completion Theory (Wicklund & Gollwitzer): जब हम किसी आदर्श का प्रतीक धारण करते हैं, तो हमारा आत्मविश्वास और कार्य-क्षमता वास्तव में बढ़ जाती है। एथलीट के jersey number से लेकर सेना के badges तक — प्रतीक हमें अपने उद्देश्य से जोड़ते हैं।`,
    lifeLesson: `अपने लिए एक ऐसा प्रतीक, आदर्श या मंत्र चुनो जो कठिन क्षणों में तुम्हें याद दिलाए — तुम कौन हो और क्यों लड़ रहे हो।`,
  },
  '1:28': {
    explanation: `अर्जुन के कांपते अंग, सूखा मुख और शिथिल शरीर — ये गहरे मानसिक तनाव के शारीरिक संकेत हैं। वह योद्धाओं को शत्रु नहीं, "अपने लोग" देख रहा है। "स्वजन" शब्द का उच्चारण यहाँ केंद्रीय है — अर्जुन की आसक्ति उसके योद्धा-धर्म से टकरा रही है। वह जानता है कि क्षत्रिय-धर्म युद्ध करना है, पर उसका हृदय परिवार-स्नेह से जकड़ा है। यही आसक्ति और धर्म के बीच का द्वंद्व गीता का प्रमुख विषय है। कृष्ण इसी द्वंद्व को समाधान करेंगे।`,
    science: `अर्जुन के लक्षण — कंपन, शुष्क मुख, शरीर का शिथिल पड़ना — Acute Stress Response के क्लासिक संकेत हैं। Cortisol और Adrenaline का अचानक स्राव होता है जब मस्तिष्क किसी परिचित व्यक्ति को "शत्रु" की श्रेणी में रखने को बाध्य होता है — यही Cognitive Dissonance है।`,
    lifeLesson: `जब शरीर में घबराहट हो, यह संकेत है कि मन किसी गहरे द्वंद्व में है। रुको, गहरी श्वास लो — भय को पहचानना ही उसे शक्ति में बदलने का पहला कदम है।`,
  },
  '1:31': {
    explanation: `अर्जुन को अशुभ संकेत इसलिए दिखते हैं क्योंकि उसकी दृष्टि आसक्ति से ढकी हुई है। जो उसका धर्म है — क्षत्रिय का युद्ध — वही उसे शारीरिक संबंधों के कारण अशुभ लगता है। वह कहता है कि राज्य-सुख कोई प्रयोजन नहीं, और न जीवन ही — यदि इसके लिए अपनों का वध करना पड़े। यह अर्जुन का स्वार्थ-त्याग नहीं, बल्कि आसक्ति-जनित भ्रम है — वह शरीर-संबंधों को आत्मा से अधिक सत्य मान रहा है।`,
    science: `Negativity Bias (Kahneman & Tversky): मानव मस्तिष्क खतरे को लाभ से 2-3 गुना अधिक भार देता है। जब अर्जुन "अपशकुन" देखते हैं, वे वास्तव में अपनी आंतरिक भय-अवस्था को बाहर प्रक्षेपित कर रहे हैं — Confirmation Bias का जीवंत उदाहरण।`,
    lifeLesson: `जब सब कुछ बुरा लगे, तो एक क्षण रुककर पूछो — क्या यह वास्तविकता है, या मेरे भय का प्रक्षेपण? मन की अवस्था बदलो, और संसार बदला हुआ दिखेगा।`,
  },
  '1:46': {
    explanation: `अर्जुन विषाद की चरम सीमा पर है। वह कहता है — "गांडीव धनुष मुझे भारी लग रहा है" — वही धनुष जो कुछ ही क्षण पूर्व उठाने में तत्पर था। वह अपने सैनिक साथियों को भूलकर, अपने हितैषियों को याद कर रहा है। उसका मन पलायन की ओर मुड़ गया है — वह युद्ध नहीं, भिक्षा-जीवन को श्रेष्ठ मानने लगा है। यही वह संकट-बिंदु है जहाँ अर्जुन का राजा-होना टूटता है और शिष्य-होना जन्म लेता है।`,
    science: `यह Learned Helplessness (Seligman, 1972) का पाठ्यपुस्तक उदाहरण है — जब व्यक्ति इतना अभिभूत हो जाता है कि निष्क्रियता ही श्रेष्ठ विकल्प लगती है। यह मानसिक अवसाद (Depression) का प्रारंभिक चरण है जिसे गीता का पूरा उपदेश ठीक करने के लिए आता है।`,
    lifeLesson: `जब "कुछ न करना" सबसे सुरक्षित लगने लगे — यह पलायन है, समाधान नहीं। यही वह संकट-बिंदु है जहाँ से वास्तविक परिवर्तन शुरू होता है।`,
  },
  '1:47': {
    explanation: `अर्जुन अपने क्षत्रिय-धर्म के साधन — धनुष-बाण — छोड़ देता है और रथ के पिछले भाग में बैठ जाता है। उसका बैठ जाना पराजय का संकेत है — यहीं से कृष्ण की शिक्षा आरंभ होती है। अर्जुन का टूटना उसके बनने की शुरुआत है। वह योद्धा के रूप में टूटता है, पर शिष्य के रूप में जन्म लेता है। यही वह बिंदु है जहाँ भौतिक-युद्ध से आध्यात्मिक-युद्ध का संक्रमण होता है।`,
    science: `किसी भी मनोचिकित्सक को यह दृश्य Clinical Depression का textbook presentation लगेगा — withdrawal (युद्ध से दूर हटना), helplessness (हथियार डालना), और emotional overwhelm। यही गहरा संकट गीता के उपदेश की नींव है।`,
    lifeLesson: `जीवन के सबसे बड़े सबक अक्सर सबसे गहरे संकट में मिलते हैं। अर्जुन का टूटना ही उसके बनने की शुरुआत थी। अपने टूटने को भी एक आरंभ मानो।`,
  },
  '2:11': {
    explanation: `कृष्ण अर्जुन के विरोधाभास को सीधे उजागर करते हैं: वह ज्ञानी की तरह बातें करता है ("न हन्तव्यम्" — न मारना चाहिए), पर अज्ञानी की तरह शोक करता है। कृष्ण कहते हैं — "पण्डिताः न शोचन्ति" — ज्ञानी न शोक करते हैं न उद्वेग। यहाँ गीता का मूल विश्लेषण है: शोक का मूल कारण अज्ञान है — आत्मा के स्वरूप का न जानना। ज्ञानी जानते हैं कि आत्मा नित्य है, न जन्मती है न मरती है। शरीर का विनाश आत्मा का विनाश नहीं। यही ज्ञान शोक का मूल उपचार है।`,
    science: `Cognitive Behavioral Therapy (CBT) का मूल सिद्धांत: विचार, भावना और व्यवहार के बीच असंगति (Cognitive Inconsistency) ही अधिकांश मानसिक पीड़ा का कारण है। कृष्ण यहाँ एक Master Therapist की तरह अर्जुन की इस असंगति को सीधे इंगित करते हैं।`,
    lifeLesson: `क्या तुम वह करते हो जो तुम जानते हो? ज्ञान और आचरण के बीच की खाई ही दुख का मूल है। आज एक ऐसे विश्वास को पहचानो जो तुम्हारे जीवन में दिखाई नहीं देता।`,
  },
  '2:13': {
    explanation: `आत्मा (जीवात्मा) शरीर की निवासी है। जैसे जीवन में बाल्य, यौवन और वृद्धावस्था आती है — शरीर के स्वाभाविक परिवर्तन — वैसे ही शरीर बदलना भी एक स्वाभाविक परिवर्तन है। मृत्यु शरीर का बदलना है, आत्मा का नाश नहीं। जैसे पुराने वस्त्र त्यागकर नए ग्रहण किए जाते हैं, वैसे ही आत्मा पुराने शरीर त्यागकर नए शरीर ग्रहण करती है। यह समझ मृत्यु के भय को मूल से दूर करती है।`,
    science: `जीव विज्ञान दर्शाता है कि लगभग हर 7 वर्ष में हमारे शरीर के अधिकांश परमाणु बदल जाते हैं। कोशिकाएँ मरती हैं, नई बनती हैं। तुम वही शरीर नहीं हो जो 5, 25 या 75 वर्ष की आयु में था — फिर भी तुम्हारा "मैं" का बोध निरंतर बना रहता है। यही निरंतरता पदार्थ से परे किसी तत्व की ओर संकेत करती है।`,
    lifeLesson: `परिवर्तन ही एकमात्र स्थिरता है। अंत पर — चाहे वह संबंध हो, नौकरी हो, या जीवन का कोई चरण — कम शोक करो। हर परिवर्तन एक संक्रमण है, समाप्ति नहीं।`,
  },
  '2:14': {
    explanation: `कृष्ण तितिक्षा (धैर्यपूर्वक सहन) का अभ्यास बताते हैं। शीत-उष्ण, सुख-दुःख जैसे द्वंद्व इन्द्रिय-सम्पर्क से उत्पन्न होते हैं, वास्तविकता से नहीं। वे आते-जाते हैं, अनित्य हैं। मूल शिक्षा यह है कि दुःख बाहरी घटनाओं से नहीं, बल्कि उन पर हमारी प्रतिक्रिया से उत्पन्न होता है। तितिक्षा से मनुष्य संवेदनाओं को बिना प्रतिक्रिया के देखना सीखता है — यही समता की नींव है।`,
    science: `भावनात्मक नियमन का तंत्रिका-विज्ञान (प्रीफ्रंटल कॉर्टेक्स द्वारा एमिग्डाला का नियमन): संवेदनाओं को तुरंत प्रतिक्रिया दिए बिना देखने की क्षमता ही भावनात्मक नियमन का मूल है। माइंडफुलनेस ध्यान पर शोध दर्शाते हैं कि साधक भावनात्मक प्रतिक्रियाशीलता पर प्रीफ्रंटल नियंत्रण विकसित कर लेते हैं, जिससे स्वतः उठने वाली प्रतिक्रियाओं से होने वाला दुःख घट जाता है।`,
    lifeLesson: `अगली बार जब असुविधा अनुभव हो — शारीरिक या भावनात्मक — प्रतिक्रिया से पहले रुको। पूछो: क्या यह संवेदना स्थायी है? क्या यह बीत जाएगी? क्या मैं इसे बिना निर्णय के केवल देख सकता हूँ? यही तितिक्षा का अभ्यास है — आंतरिक शांति का द्वार।`,
  },
  '2:27': {
    explanation: `कृष्ण अस्तित्व का मूल नियम बताते हैं: जन्म-मृत्यु का चक्र सभी देहधारियों के लिए अनिवार्य है। जन्म और मृत्यु दोनों निश्चित (ध्रुव) हैं। तर्क सरल है — अनिवार्य का शोक करने से व्यर्थ दुःख उत्पन्न होता है। ज्ञानी जो बदला नहीं जा सकता उसे स्वीकार करते हैं और अपनी ऊर्जा वहाँ लगाते हैं जो बदला जा सकता है — अपनी आंतरिक अवस्था।`,
    science: `स्टोइक दर्शन और Acceptance and Commitment Therapy (ACT): दोनों उसी को स्वीकारने पर बल देते हैं जिसे नियंत्रित नहीं किया जा सकता। मनोवैज्ञानिक लचीलेपन (psychological flexibility) पर शोध दर्शाते हैं कि अनिवार्य परिस्थितियों को स्वीकारना — अनियंत्रित घटनाओं को नियंत्रित करने के प्रयास की तुलना में — दुःख को अधिक घटाता है।`,
    lifeLesson: `अपने जीवन में कोई एक अनिवार्य बात पहचानो — वृद्धावस्था, परिवर्तन, हानि। उसका विरोध करने के बजाय स्वीकार का अभ्यास करो। यह निष्क्रियता नहीं है; यह वास्तविकता से लड़ने में ऊर्जा न गँवाना है, ताकि वह ऊर्जा सार्थक कर्म में लगे।`,
  },
  '2:20': {
    explanation: `यह गीता का अत्यंत प्रसिद्ध श्लोक है। आत्मा के चार विशेषण: अज: (जन्म रहित), नित्य: (शाश्वत), शाश्वत: (सदा रहने वाला), पुराण: (आदिकालीन)। आत्मा जन्मती नहीं, मरती नहीं — वह केवल शरीर के जन्म-मृत्यु की साक्षी है। शरीर के विनाश से आत्मा नहीं मरती, जैसे वस्त्र के फटने से उसे पहनने वाला नहीं मरता। यह ज्ञान शोक और भय दोनों को समाप्त करता है — क्योंकि जो कभी जन्मता-मरता नहीं, उसके लिए विनाश का भय ही नहीं।`,
    science: `ऊर्जा संरक्षण का नियम (आइंस्टीन): "ऊर्जा न तो उत्पन्न की जा सकती है, न नष्ट — केवल रूपांतरित होती है।" कई तंत्रिका-वैज्ञानिक अब (Penrose-Hameroff "Orch-OR" सिद्धांत) तर्क देते हैं कि चेतना स्वयं ब्रह्मांड का एक मूलभूत गुण हो सकती है — मस्तिष्क द्वारा उत्पन्न नहीं।`,
    lifeLesson: `तुम अपना शरीर नहीं हो। मृत्यु का भय तब विलीन हो जाता है जब मनुष्य उस शाश्वत चेतना से अपनी पहचान जोड़ता है जो शरीर के जन्म, वृद्धि और मृत्यु — सबकी साक्षी है।`,
  },
  '2:38': {
    explanation: `कृष्ण समता-योग का परिचय देते हैं। आसक्ति रहित कर्म की कुंजी है द्वंद्वों को समान मानना — भावनाओं को दबाकर नहीं, बल्कि बाहरी परिणामों के बावजूद आंतरिक संतुलन बनाए रखकर। जब कर्म लालसा या द्वेष के ज्वर के बिना किया जाता है, तब वह निष्पाप हो जाता है।`,
    science: `भावनात्मक नियमन और समता पर शोध (Kabat-Zinn): बाहरी घटनाओं के बावजूद स्थिर भावनात्मक अवस्था बनाए रखने की क्षमता मनोवैज्ञानिक दृढ़ता की पहचान है। अध्ययन दर्शाते हैं कि समता-प्रशिक्षण एमिग्डाला की प्रतिक्रियाशीलता घटाता है और प्रीफ्रंटल कॉर्टेक्स के नियमन को बढ़ाता है।`,
    lifeLesson: `आज दैनिक जीवन की छोटी जीत और हार को समान भाव से लेने का अभ्यास करो। किसी ने ट्रैफ़िक में रास्ता काट दिया? उसे वैसे ही लो जैसे किसी ने रास्ता दे दिया हो। यही "समता" की मांसपेशी बड़ी चुनौतियों में शक्ति बनती है।`,
  },
  '2:47': {
    explanation: `कृष्ण निष्काम कर्म (आसक्ति रहित कर्म) सिखाते हैं। मनुष्य का अधिकार कर्म पर है, फल (परिणाम) पर नहीं। फल की आसक्ति बंधन बनती है, और कर्म से पलायन जड़ता।`,
    science: `मनोविज्ञान इसे "process-focus" बनाम "outcome-focus" कहता है। Carol Dweck आदि के शोध दर्शाते हैं कि प्रक्रिया पर केंद्रित (growth mindset) व्यक्ति, परिणाम पर अटके व्यक्तियों से बेहतर प्रदर्शन करते हैं। श्रेष्ठ खिलाड़ी, शल्य-चिकित्सक और वैज्ञानिक बार-बार बताते हैं कि flow अवस्था तभी आती है जब परिणाम की आसक्ति छूट जाती है।`,
    lifeLesson: `अपना 100% प्रयास में लगाओ, परिणाम से विरक्त रहो। चिंता और कुछ नहीं — भविष्य के परिणामों को छोड़ने से मन का इनकार है। जो तुम्हारे वश में है — आज का कर्म — उस पर ध्यान दो, और शांति स्वतः आती है।`,
  },
  '3:19': {
    explanation: `कृष्ण कर्मयोग का सार प्रस्तुत करते हैं: आसक्ति रहित कर्म मन को शुद्ध करता है। कर्म छोड़ना समाधान नहीं — क्योंकि कर्म न करना भी कर्म है, और निष्क्रियता जड़ता उत्पन्न करती है। कर्तव्य करते हुए फल से मुक्त रहना ही योग का मार्ग है। जो फल की आसक्ति से कर्म करता है, वह बंधन में पड़ता है; जो निष्काम भाव से कर्म करता है, वह मुक्त हो जाता है। यह गीता का केंद्रीय सिद्धांत है — कर्म से नहीं, आसक्ति से बंधन होता है।`,
    science: `Mihaly Csikszentmihalyi का flow-state शोध: सर्वोच्च प्रदर्शन तब आता है जब व्यक्ति परिणाम के प्रति आत्म-चेतना छोड़कर पूरी तरह कर्म में लीन हो जाता है। यही गीता की असक्ति (अनासक्ति) है, जिसे संज्ञानात्मक मनोविज्ञान प्रमाणित करता है।`,
    lifeLesson: `प्रेरणा की प्रतीक्षा करना बंद करो। कर्तव्य की दिशा में कर्म करो, स्पष्टता स्वतः आएगी। निष्क्रियता टालमटोल का सबसे ऊँचा स्वर है; अनासक्त कर्म उसका उपचार।`,
  },
  '3:30': {
    explanation: `यह अवतारवाद की प्रसिद्ध घोषणा है। कृष्ण यह नहीं कहते कि वे केवल दुष्टता का नाश करने अवतरित होते हैं; वे तब अवतरित होते हैं जब धर्म क्षीण होता है। बल विनाश पर नहीं, पुनर्स्थापन पर है। दिव्य प्रतिक्रिया दंडात्मक नहीं, पुनर्स्थापनात्मक है।`,
    science: `सिस्टम्स थ्योरी: हर स्थिर तंत्र में स्व-सुधारक तंत्र (negative feedback) होता है। जब एन्ट्रॉपी (अव्यवस्था, अधर्म) बढ़ती है, तब सुधारात्मक शक्तियाँ उभरती हैं — जैविक, सामाजिक और ब्रह्मांडीय स्तर पर। ब्रह्मांड स्वयं को संतुलित करता है।`,
    lifeLesson: `अपने सबसे अंधकारमय समय में भी एक आंतरिक दिशासूचक है जो संतुलन बहाल करने उठ खड़ा होता है। प्रक्रिया पर विश्वास रखो। इतिहास गवाह है — हर अंधकार-युग ने अपने प्रकाश-पुरुष जन्मे हैं।`,
  },
  '3:35': {
    explanation: `सर्वाधिक व्यावहारिक श्लोकों में से एक। दूसरे का मार्ग, चाहे पूर्णता से निभाया जाए, संकटपूर्ण है क्योंकि वह तुम्हारे स्वभाव से मेल नहीं खाता। अपना स्वधर्म, चाहे अपूर्ण रूप से निभे, सच्ची उन्नति की ओर ले जाता है।`,
    science: `Self-Concordance Theory (Sheldon & Elliot, 1999): जो लक्ष्य व्यक्ति के अंतर्निहित मूल्यों और स्वभाव से मेल खाते हैं, उनकी प्राप्ति दर और कल्याण दोनों अधिक होते हैं। बाहर से आए मानकों के अनुसार चलना — चाहे कितना भी प्रभावशाली क्यों न हो — burnout और असंतोष उत्पन्न करता है।`,
    lifeLesson: `अपने स्वभाव को पहचानो — तुम्हारी प्राकृतिक प्रवृत्ति क्या है? दूसरों की सफलता की नकल करने के बजाय अपने स्वधर्म में उत्कृष्टता की ओर बढ़ो। अपूर्णता में भी सच्चाई है।`,
  },
  '3:42': {
    explanation: `कृष्ण एक गहन सामाजिक-मनोवैज्ञानिक सत्य बताते हैं: श्रेष्ठ व्यक्ति का आचरण समाज के लिए प्रमाण बनता है। जनसाधारण अपने आदर्शों का अनुसरण करते हैं। अर्जुन जैसे राजकुमार का धर्म है कि वह कर्म से लोक के लिए सही उदाहरण रखे — क्योंकि उसका आचरण हजारों को प्रभावित करता है। यही नेतृत्व का आध्यात्मिक सिद्धांत है: नेता का व्यक्तिगत आचरण सामूहिक आचरण का आधार बनता है।`,
    science: `Social Learning Theory (Bandura, 1977): मनुष्य एक Observational Learning प्राणी है। Mirror Neurons (Rizzolatti) की खोज ने सिद्ध किया — हमारा मस्तिष्क दूसरों के कार्यों को अपने भीतर simulate करता है। इसीलिए एक व्यक्ति का आचरण पूरे समाज को प्रभावित करता है।`,
    lifeLesson: `तुम एक जीवित उदाहरण हो — चाहे जानो या न जानो। तुम्हारे बच्चे, साथी, सहकर्मी — सब तुम्हें देख रहे हैं। जो व्यवहार तुम दूसरों में देखना चाहते हो, वह पहले स्वयं प्रकट करो।`,
  },
  '4:7': {
    explanation: `कृष्ण अवतारवाद की मूल घोषणा करते हैं: जब-जब धर्म क्षीण होता है और अधर्म बढ़ता है, तब-तब वे स्वयं अवतरित होते हैं। यह केवल ऐतिहासिक वर्णन नहीं — यह ब्रह्मांडीय सिद्धांत है। धर्म = ब्रह्मांडीय व्यवस्था, संतुलन, सत्य का प्रवाह। अधर्म = विकृति, असंतुलन, असत्य का आग्रह। जब व्यवस्था विकृत होती है, तब स्वयं सत्य शक्ति रूप में प्रकट होकर संतुलन बहाल करता है। यही अवतारवाद की मूल भावना है।`,
    science: `सिस्टम्स थ्योरी और ऊष्मागतिकी: हर स्थिर तंत्र में एक स्व-सुधारक तंत्र (negative feedback) होता है। जब एन्ट्रॉपी (अव्यवस्था, अधर्म) बढ़ती है, तब सुधारात्मक शक्तियाँ उभरती हैं — जैविक, सामाजिक और ब्रह्मांडीय स्तर पर। ब्रह्मांड स्वयं को संतुलित करता है।`,
    lifeLesson: `अपने सबसे अंधकारमय समय में भी एक आंतरिक दिशासूचक है जो संतुलन बहाल करने उठ खड़ा होता है। प्रक्रिया पर विश्वास रखो। इतिहास गवाह है — हर अंधकार-युग ने अपने प्रकाश-पुरुष जन्मे हैं।`,
  },
  '4:8': {
    explanation: `अवतार का उद्देश्य व्यक्तिगत नहीं, ब्रह्मांडीय है: सज्जनों (साधुओं) की रक्षा, दुष्टता (दुष्कृतियों) का विनाश, और धर्म का पुनर्स्थापन। यह चार गुणों का संकलन है — परित्राण, विनाश, संस्थापन, और अवतार-स्वरूप। अवतार दंडात्मक नहीं, पुनर्स्थापनात्मक है — उसका लक्ष्य विनाश नहीं, संतुलन बहाल करना है। दुष्टता का विनाश उसी संतुलन का अंग है।`,
    science: `Systems Theory में इसे Negative Feedback Loop कहते हैं — जब किसी तंत्र में विकार बढ़ता है, स्वतः सुधारात्मक शक्तियाँ उभरती हैं। जैव-विकास (Evolution) में भी: जब पारिस्थितिकी असंतुलित होती है, नई प्रजातियाँ और शक्तियाँ उभरकर संतुलन बहाल करती हैं।`,
    lifeLesson: `इतिहास में हर अंधेरे युग ने अपना प्रकाश-पुरुष जन्मा है। अपने परिवार, समाज या कार्यक्षेत्र में जहाँ अधर्म दिखे — वहाँ खड़े होने का साहस रखो। हर युग को अपने अवतार चाहिए।`,
  },
  '5:10': {
    explanation: `कृष्ण संन्यास को जीवन से भागना नहीं, बल्कि स्वामित्व की भावना बदलना बताते हैं। कर्म चलता रहता है, पर अहंकार उसे "मेरा" कहकर पकड़ता नहीं और फल से चिपकता नहीं। कमल-पत्र जल में रहता है, पर जल उसे भिगो नहीं पाता; योगी संसार में रहता है, पर संसार उसे अपने भीतर डुबो नहीं पाता।`,
    science: `मनोविज्ञान involvement और over-identification में अंतर करता है। व्यक्ति पूरे प्रयास से काम कर सकता है और फिर भी परिणामों से स्वस्थ दूरी रख सकता है; इससे तनाव-प्रतिक्रिया घटती है और लचीलापन बढ़ता है। यह श्लोक आधुनिक performance psychology से बहुत पहले उसी स्वस्थ अनासक्ति को समझाता है।`,
    lifeLesson: `काम पूरी तरह करो, पर काम को अपनी पहचान पर चिपकने मत दो। कर्म अर्पित करो, फल छोड़ो, और जल में कमल-पत्र की तरह स्वच्छ रहो।`,
  },
  '6:5': {
    explanation: `कृष्ण एक अद्भुत सत्य बताते हैं: मन मनुष्य का सबसे बड़ा मित्र भी हो सकता है और सबसे बड़ा शत्रु भी। जिसने मन को जीत लिया, उसके लिए मन मित्र बन जाता है; जो मन के वश में है, उसके लिए मन शत्रु बन जाता है। योग (आत्म-संयम) का सार मन की दिशा बदलना है — मन को बाहर की ओर खींचने से रोककर आत्मा की ओर मोड़ना। यह उन्नत आत्मा का लक्षण है।`,
    science: `तंत्रिका-विज्ञान: प्रीफ्रंटल कॉर्टेक्स (कार्यकारी कार्य) एमिग्डाला (भावनात्मक केंद्र) का नियमन कर सकता है। ध्यान जैसी साधनाएँ शाब्दिक रूप से प्रीफ्रंटल कॉर्टेक्स को मोटा करती हैं और भय-परिपथों को कमजोर करती हैं — मस्तिष्क आत्म-स्वामित्व की ओर पुनर्संरचित होता है।`,
    lifeLesson: `तुम अपनी सबसे बड़ी बाधा भी हो और अपने एकमात्र संभव उद्धारक भी। प्रतिदिन स्वयं को उन्नत करने की आदत बनाओ; कोई बाहरी शक्ति तुम्हें उतनी विश्वसनीयता से नहीं उठा सकती जितना तुम्हारा अनुशासित मन।`,
  },
  '6:6': {
    explanation: `जिसने मन को जीत लिया, उसके लिए मन सहयोगी बन जाता है — वह शांति में स्थित होता है। अनियंत्रित मन बाहरी सफलता के बावजूद मनुष्य को आंतरिक बंधन में रखता है। यह श्लोक बताता है कि वास्तविक विजय बाहरी नहीं, आंतरिक है — मन को वश में करना ही सच्ची विजय है।`,
    science: `Neuroscience: Prefrontal Cortex (तर्कशील मस्तिष्क) और Amygdala (भावनात्मक प्रतिक्रिया-केंद्र) के बीच निरंतर संघर्ष होता है। fMRI अध्ययनों में पाया गया: दीर्घकालिक ध्यान-साधकों में Prefrontal Cortex मोटी होती है और Amygdala की प्रतिक्रिया कम होती है — मस्तिष्क शाब्दिक रूप से rewire हो जाता है।`,
    lifeLesson: `मन को दबाओ मत — उसे प्रशिक्षित करो। रोज़ 10-15 मिनट का ध्यान, journaling या गहरी श्वास — ये छोटे अभ्यास धीरे-धीरे मस्तिष्क की संरचना बदल देते हैं।`,
  },
  '7:7': {
    explanation: `कृष्ण स्वयं को परम आधार बताते हैं। जैसे मोती धागे पर टिके रहते हैं, वैसे ही पूरा जगत ईश्वर पर आधारित है। यह केवल एक धार्मिक दावा नहीं — यह अद्वैत का सिद्धांत है। सभी रूप, सभी वस्तुएँ, सभी घटनाएँ एक ही परम तत्व से उत्पन्न होती हैं और उसी में लीन होती हैं। वही तत्व कृष्ण कहते हैं — "मत्तः परतरं नान्यत्" — मुझसे अतिरिक्त और कुछ नहीं।`,
    science: `Quantum Field Theory और String Theory: सभी भिन्न-भिन्न दिखने वाले कण वास्तव में एक ही मूलभूत क्षेत्र (field) की अभिव्यक्तियाँ हैं। David Bohm का Implicate Order सिद्धांत: ब्रह्मांड एक अखंड सत्ता है जिसमें से विविधता प्रकट होती है — गीता के "सूत्रे मणिगणा इव" की वैज्ञानिक प्रतिध्वनि।`,
    lifeLesson: `एकांत में बैठकर अनुभव करो — तुम सब चीजों से जुड़े हो। तुम्हारी श्वास, जल, सूर्य का प्रकाश, तुम्हारे विचार — सब एक ही जाल के हिस्से हैं। यह बोध अहंकार को पिघला देता है।`,
  },
  '7:8': {
    explanation: `कृष्ण बताते हैं कि ईश्वर दूर नहीं है — वह हर अनुभव के सार में उपस्थित है। जल का रस, सूर्य का प्रकाश, ओंकार (ॐ = सृष्टि का मूल नाद) और शक्ति में दिव्यता को पहचानना ज्ञान का मार्ग है। यह सगुण उपासना का सिद्धांत है — ईश्वर को साकार रूप में नहीं, बल्कि अनुभव के सार में खोजना। जो जल के स्वाद में ईश्वर को पहचानता है, वह ईश्वर को जानता है।`,
    science: `Panpsychism — रोजर पेनरोज़ जैसे अग्रणी भौतिकविदों और डेविड चामर्स जैसे दार्शनिकों द्वारा समर्थित सिद्धांत — प्रस्तावित करता है कि चेतना ब्रह्मांड का एक मूलभूत गुण हो सकती है, जो हर परमाणु में व्याप्त है। यह गीता की सर्वव्यापी दिव्यता की प्रतिध्वनि है।`,
    lifeLesson: `साधारण क्षणों में दिव्यता को देखना सीखो — जल का स्वाद, सूर्य की गर्मी, वाणी की शक्ति। दैनिक अनुभव के प्रति श्रद्धा जीवन को उपासना में बदल देती है।`,
  },
  '8:5': {
    explanation: `कृष्ण अंतिम समय के महत्व पर बल देते हैं। अंतिम समय का स्मरण जीवन भर की साधना से बनता है। जो जीवन में ईश्वर को याद करता है, मृत्यु के क्षण में भी वही स्मरण बना रहता है। और जो मृत्यु के क्षण में ईश्वर को याद करता है, वह ईश्वर को प्राप्त होता है। यह अभ्यास की शक्ति है — जीवन भर का अभ्यास अंतिम क्षण में फल देता है।`,
    science: `Neuroscience of habit (BJ Fogg, Charles Duhigg): मृत्यु के क्षणों में brain activity, जीवनभर की सबसे गहरी mental conditioning को reflect करती है। जो विचार-पैटर्न हम बार-बार अभ्यास करते हैं, वे neural pathways बन जाती हैं। अंतिम विचार जीवन-भर की practice का फल है।`,
    lifeLesson: `मृत्यु-शैया पर जो विचार हो, वह आज की आदत पर निर्भर है। अभी से अपने दैनिक विचारों का अवलोकन करो — जो प्रतिदिन मन में आता है, वही अंत में भी आएगा।`,
  },
  '8:7': {
    explanation: `कृष्ण अर्जुन को भक्ति और कर्तव्य का संयोग सिखाते हैं। मन-बुद्धि ईश्वर को अर्पित करके अपने सांसारिक धर्म का पालन करो। युद्ध करते हुए भी मन ईश्वर में लगा रहे — यही सच्ची भक्ति है। भक्ति और कर्तव्य विरोधी नहीं, पूरक हैं। जो कर्म ईश्वर-समर्पण से किया जाता है, वह भक्ति बन जाता है।`,
    science: `Dual-task automaticity research (Shiffrin & Schneider, 1977): गहन अभ्यास से दो कार्य एक साथ automatic हो जाते हैं। प्रशिक्षित शल्य-चिकित्सक, खिलाड़ी और संगीतकार संकट में भी शांति से perform करते हैं क्योंकि उनकी skill और awareness साथ-साथ सक्रिय रहती है — यही "युद्ध करते हुए स्मरण" है।`,
    lifeLesson: `भक्ति का अर्थ केवल मंदिर नहीं — अपने हर कार्य में पूर्ण जागरूकता और समर्पण। आज एक काम चुनो और उसे पूरी उपस्थिति (presence) के साथ करो — यही आधुनिक भक्ति है।`,
  },
  '9:22': {
    explanation: `कृष्ण अनन्य भक्तों के लिए आश्वासन देते हैं: जो निरंतर ईश्वर का स्मरण करते हैं, उनकी आवश्यकता और सुरक्षा का भार वे स्वयं उठाते हैं। "योग" का अर्थ है कमी को पूरा करना, और "क्षेम" का अर्थ है प्राप्त वस्तु की रक्षा। यह श्लोक भक्ति का सर्वोच्च आश्वासन है — ईश्वर स्वयं भक्त के भरण-पोषण का उत्तरदायित्व लेते हैं। यह निष्क्रियता का आदेश नहीं, बल्कि चिंता-मुक्त कर्म की अनुमति है।`,
    science: `धार्मिक/आध्यात्मिक अभ्यास पर अध्ययन (मनोवैज्ञानिक Koenig, Vaillant) दर्शाते हैं कि निरंतर श्रद्धा-आधारित जीवन निम्न cortisol स्तर, बेहतर प्रतिरक्षा-कार्य, रोग से तेज़ स्वास्थ्य-लाभ और संकट में अधिक दृढ़ता से जुड़ा है।`,
    lifeLesson: `विश्वास दैवी व्यवस्था (providence) को खोलता है। जब तुम्हारी ऊर्जा चिंता में खर्च होना बंद हो जाती है, तो वह बुद्धिमान कर्म के लिए उपलब्ध हो जाती है — और बुद्धिमान कर्म स्वाभाविक रूप से सही समय पर सही संसाधन आकर्षित करता है।`,
  },
  '9:27': {
    explanation: `कृष्ण उपासना के दो मार्ग बताते हैं: सगुण (साकार) और निर्गुण (निराकार)। निर्गुण, अव्यक्त ब्रह्म की उपासना भी मुक्ति की ओर ले जाती है, पर देहधारी मनुष्यों के लिए सगुण भक्ति अधिक सहज मार्ग है। मन जिस रूप को पकड़ता है, उसी में लगता है — इसलिए साकार ईश्वर का ध्यान मन को एकाग्र करने का सहज साधन है। अंततः दोनों मार्ग एक ही लक्ष्य की ओर जाते हैं।`,
    science: `निर्गुण ब्रह्म की अवधारणा गणित के "Infinity" (अनंत) जैसी है — परिभाषित करते ही वह सीमित हो जाती है। Apophatic (निषेधात्मक) Theology: ईश्वर को वह नहीं कहा जा सकता जो वह है — केवल यह कहा जा सकता है कि वह क्या नहीं है। यही उपनिषदीय परंपरा की पश्चिमी प्रतिध्वनि है।`,
    lifeLesson: `कुछ सत्य शब्दों और विचारों से परे हैं — वे केवल अनुभव से जाने जाते हैं। अपनी साधना में निराकार मौन के साथ समय बिताओ — बिना किसी अवधारणा, छवि या मंत्र के।`,
  },
  '10:20': {
    explanation: `कृष्ण अपने सर्वव्यापी स्वरूप का वर्णन करते हैं: वे सभी प्राणियों के हृदय में स्थित आत्मा हैं। वे सृष्टि की शुरुआत, मध्य और अंत — सबके आधार हैं। यह अंतर्यामी स्वरूप है — ईश्वर केवल बाहर नहीं, बल्कि हर प्राणी के भीतर स्थित है। यही अद्वैत का मूल सत्य है।`,
    science: `Panpsychism सिद्धांत (David Chalmers, Roger Penrose): चेतना ब्रह्मांड का एक मूलभूत गुण हो सकती है, जो मस्तिष्क द्वारा उत्पन्न नहीं होती। यदि यह सत्य है, तो हर कण में चेतना (awareness) है — ठीक वैसे ही जैसे गीता कहती है कि कृष्ण हर प्राणी की आत्मा हैं।`,
    lifeLesson: `जब किसी की आँखों में देखो, याद रखो — वहाँ वही चेतना है जो तुम्हारे भीतर है। यह बोध करुणा को स्वाभाविक और हिंसा को असंभव बना देता है।`,
  },
  '10:34': {
    explanation: `कृष्ण अपनी विभूतियों का वर्णन करते हुए कहते हैं कि वे सब कुछ हैं — सबसे श्रेष्ठ, सबसे शक्तिशाली, सबसे सुंदर। विश्वरूप कृष्ण की योगमाया से प्रकट हुआ विराट रूप है। पर कृष्ण का नित्य, व्यक्तिगत और सुंदर स्वरूप उससे भी गहरा आध्यात्मिक सत्य है। विभूति योग का सार यह है कि ईश्वर को सब कुछ में पहचानना — हर श्रेष्ठ वस्तु ईश्वर की अभिव्यक्ति है।`,
    science: `भौतिकी में Observer Effect: क्वांटम यांत्रिकी में किसी घटना को observe करने का कार्य ही उसे बदल देता है। सभी वैज्ञानिक models (Newton → Einstein → Quantum) अस्थायी रूप हैं — गहरी वास्तविकता के "snapshots"। विश्वरूप भी कृष्ण का वही रूप था जो अर्जुन की धारणा-क्षमता के अनुरूप ढाला गया।`,
    lifeLesson: `जो दिखता है वह पूरी सच्चाई नहीं है। हमारे सभी models, narratives और perceptions अस्थायी हैं। जिज्ञासा रखो, किसी भी "final answer" को अंतिम मत मानो।`,
  },
  '11:32': {
    explanation: `अर्जुन कृष्ण का विश्वरूप देखता है, जो अनंत, भयावह और महिमामय है। कृष्ण कहते हैं — "कालोऽस्मि" — मैं काल हूँ, संसार का विनाशक। हजार सूर्यों की उपमा उसकी असहनीय दिव्य चमक को व्यक्त करती है। यह रूप सृष्टि का सत्य है — उत्पत्ति और विनाश एक ही सत्य के दो रूप हैं। अर्जुन भय और विस्मय दोनों अनुभव करता है।`,
    science: `J. Robert Oppenheimer ने Trinity Nuclear Test (1945) के बाद इसी श्लोक को उद्धृत किया। Nuclear fission में E=mc² — एक सूक्ष्म परमाणु से असीम ऊर्जा का विमोचन। वैज्ञानिक भी इस श्लोक की भाषा में ब्रह्मांड की असीम शक्ति का वर्णन खोजते हैं।`,
    lifeLesson: `कुछ अनुभव शब्दों से परे हैं — जन्म, मृत्यु, प्रेम, ब्रह्मांड की विशालता। इनके सामने विनम्र रहो। विज्ञान भी ऐसे ही "cosmic awe" से बढ़ता है — आइंस्टीन ने कहा था: "सबसे सुंदर वस्तु रहस्यमय है।"`,
  },
  '12:13': {
    explanation: `कृष्ण आदर्श भक्त के लक्षण बताते हैं। सच्चा भक्त सुख-दुःख (द्वंद्व), मान-अपमान, मित्र-शत्रु में समभाव (समत्व) रखता है। वह सरल, दयालु, क्षमाशील और बिना आसक्ति के होता है। यह भक्ति केवल भावुकता नहीं — यह चरित्र की परिपक्वता है। समता ही भक्ति का मूल है।`,
    science: `भावनात्मक तंत्रिका-विज्ञान दर्शाता है कि भावनात्मक समता एक प्रशिक्षित कौशल है: दीर्घकालिक साधकों में तनावकारकों के प्रति एमिग्डाला की प्रतिक्रिया मापने योग्य रूप से कम होती है — इसे "affective resilience" कहते हैं। मस्तिष्क अभ्यास से शाब्दिक रूप से स्वयं को पुनर्गठित कर लेता है।`,
    lifeLesson: `तुम्हारी शांति संसार के मौसम पर निर्भर न हो। प्रतिक्रिया के बजाय सोच-समझकर उत्तर देने का अभ्यास करो। एक भावनात्मक रूप से स्थिर व्यक्ति, एक प्रतिक्रियाशील प्रतिभाशाली से, स्वयं और समाज के लिए अधिक मूल्यवान है।`,
  },
  '12:15': {
    explanation: `कृष्ण आदर्श भक्त का और वर्णन करते हैं: वह न संसार को व्याकुल करता है, न संसार से व्याकुल होता है। हर्ष, ईर्ष्या, भय और चिंता से मुक्त होना परिपक्व भक्ति का लक्षण है। ऐसा भक्त जीवन में पूर्णतः उपस्थित रहता है, पर किसी भी परिस्थिति से विचलित नहीं होता। यही समता की परिपक्वता है।`,
    science: `Emotional Contagion research (Hatfield, 1993): मनुष्य अनजाने में दूसरों की भावनाएँ "catch" करते हैं। EEG अध्ययन: अनुभवी ध्यान-साधकों की brainwaves आसपास के लोगों को coherence (सामंजस्य) की ओर ले जाती हैं। एक स्थिर व्यक्ति वास्तव में अपने आसपास की भावनात्मक climate को बदल देता है।`,
    lifeLesson: `तुम्हारी आंतरिक शांति एक सार्वजनिक सेवा है। जब तुम भय और उद्वेग से मुक्त होते हो, तुम हर उस व्यक्ति के लिए एक anchor (आधार) बन जाते हो जो तुम्हारे जीवन में आता है।`,
  },
  '13:2': {
    explanation: `कृष्ण मूलभूत तत्त्व-मीमांसीय भेद बताते हैं: "क्षेत्र" (शरीर, मन, इन्द्रियाँ और उनके सभी विकार) और "क्षेत्रज्ञ" (शुद्ध चेतना)। शरीर क्षेत्र है — वह बदलता, बूढ़ा होता, मरता है। क्षेत्रज्ञ शाश्वत साक्षी है। क्षेत्र से तादात्म्य अज्ञान है; स्वयं को क्षेत्रज्ञ जानना ही ज्ञान है।`,
    science: `तंत्रिका-विज्ञान की "hard problem": मस्तिष्क (क्षेत्र) को पूरी तरह मानचित्रित किया जा सकता है, फिर भी व्यक्तिपरक अनुभवकर्ता (क्षेत्रज्ञ) अनिर्वचनीय रह जाता है। IIT (Tononi) जैसे सिद्धांत चेतना को मस्तिष्क में खोजने का प्रयास करते हैं, पर जो साक्षी मस्तिष्क की गतिविधि को देखता है, वह सदा किसी भी भौतिक वर्णन से एक कदम परे प्रतीत होता है — ठीक वही भेद जो गीता खींचती है।`,
    lifeLesson: `जब तुम कहते हो "मेरा मन व्याकुल है" या "मेरा शरीर थका है" — ध्यान दो: यह "मेरा" कौन है? एक साक्षी है जो व्याकुलता और थकान को देखता है। वही क्षेत्रज्ञ है। व्याकुल मन या थके शरीर बनने के बजाय उस साक्षी-पहचान में टिकने का अभ्यास करो।`,
  },
  '13:28': {
    explanation: `सच्ची दृष्टि की परिभाषा: सभी अस्थायी रूपों में शाश्वत, अपरिवर्तनशील चेतना को देखना। अधिकांश लोग केवल रूप देखते हैं — भेद, विभिन्नताएँ, व्यक्तित्व। ज्ञानी उस एक चेतना को देखते हैं जो सभी रूपों को समान रूप से अनुप्राणित करती है।`,
    science: `सामाजिक तंत्रिका-विज्ञान: ऑक्सीटोसिन-प्रेरित सहानुभूति मनुष्य को दूसरों को मात्र वस्तु नहीं, बल्कि अनुभवकर्ता के रूप में देखने देती है। "theory of mind" (Premack & Woodruff) — दूसरों में चेतना का आरोपण करने की क्षमता — "सभी प्राणियों में ईश्वर को देखने" का तंत्रिकीय आधार है। गीता इसे केवल मनुष्यों तक नहीं, समस्त प्राणियों तक विस्तृत करती है।`,
    lifeLesson: `आज किसी एक ऐसे व्यक्ति को चुनो जिसे तुम सामान्यतः अनदेखा या नापसंद करते हो। उसकी आँखों में देखकर पूछो: वहाँ क्या जीवित है? कौन-सी चेतना मुझे देख रही है? यही सभी में ईश्वर को देखने का अभ्यास है — और यह संबंधों को लेन-देन से पवित्र में बदल देता है।`,
  },
  '14:5': {
    explanation: `तीन गुण समस्त पदार्थ और मन की मूलभूत संचालन-अवस्थाएँ हैं। सत्त्व = स्पष्टता, प्रकाश, सामंजस्य। रजस = ऊर्जा, आवेग, बेचैनी, महत्वाकांक्षा। तमस = जड़ता, भारीपन, मोह, आलस्य। हर विचार, भोजन, कर्म और वातावरण हमें इन तीनों में से किसी एक अवस्था की ओर धकेलता है।`,
    science: `सर्केडियन जीवविज्ञान और तंत्रिका-मनोविज्ञान: मानव मस्तिष्क भिन्न-भिन्न अवस्थाओं में कार्य करता है — सजग/स्पष्ट (सत्त्व-प्रधान), उत्तेजित/तनावग्रस्त (रजस-प्रधान), और सुस्त/धुंधला (तमस-प्रधान)। आहार, नींद, व्यायाम और वातावरण मस्तिष्क को इन अवस्थाओं के बीच मापने योग्य रूप से स्थानांतरित करते हैं। गीता का त्रिगुण-मॉडल उसी का प्राचीन अनुभवजन्य मानचित्र है जिसे तंत्रिका-विज्ञान अब शारीरिक रूप से मापता है।`,
    lifeLesson: `अपनी वर्तमान अवस्था की समीक्षा करो: क्या तुम स्पष्ट और एकाग्र हो (सत्त्व)? बेचैन और प्रेरित (रजस)? सुस्त और भारी (तमस)? फिर पीछे जाकर देखो: आज क्या खाया, कैसे सोए, क्या देखते-पढ़ते रहे? हर इनपुट तुम्हारा गुण-संतुलन बदलता है। अपनी मानसिक अवस्था पर तुम्हारा, जितना तुम सोचते हो, उससे कहीं अधिक नियंत्रण है।`,
  },
  '14:17': {
    explanation: `प्रत्येक गुण मन में अपना विशिष्ट फल उत्पन्न करता है। सत्त्व स्पष्ट ज्ञान (ज्ञान) उत्पन्न करता है। रजस लोभ उत्पन्न करता है — सदा अधिक की चाह, कभी संतोष नहीं। तमस प्रमाद और मोह उत्पन्न करता है। ये नैतिक निर्णय नहीं, बल्कि इस बात का सटीक वर्णन हैं कि भिन्न मन-अवस्थाएँ भिन्न विचार और कर्म उत्पन्न करती हैं।`,
    science: `संज्ञानात्मक तंत्रिका-विज्ञान पुष्टि करता है: उच्च-स्पष्टता अवस्थाओं में (alpha/theta तरंगों, विश्रांत प्रीफ्रंटल कॉर्टेक्स से सम्बद्ध) अंतर्दृष्टि और अधिगम अधिकतम होते हैं। उच्च-उत्तेजना अवस्थाओं में (उच्च cortisol, सहानुभूतिक सक्रियता) ध्यान तत्काल पुरस्कार-खोज तक सिमट जाता है (रजस = लोभ)। निम्न-ऊर्जा अवस्थाओं में संज्ञानात्मक कार्य भ्रम और जड़ता में बिखर जाता है (तमस)।`,
    lifeLesson: `जब लोभ या लालसा उठती दिखे (रजस), पूछो: क्या मुझे वापस सत्त्व की ओर लाएगा? प्रायः वह एक टहलना, मौन, अच्छा भोजन, संवाद या विश्राम होता है। जब आलस्य (तमस) दिखे, वही प्रश्न पूछो। गुण परिवर्तनीय हैं — तुम किसी अवस्था में बँधे नहीं हो।`,
  },
  '14:26': {
    explanation: `गुणों को पार करने का परम उपाय दमन नहीं, बल्कि भक्ति द्वारा अतिक्रमण है। जो व्यक्ति पूर्णतः सेवा-भाव से कर्म करता है — बिना किसी व्यक्तिगत स्वार्थ, बिना फल की लालसा के — वह गुणों के जाल में नहीं फँसता। वह "गुणातीत" हो जाता है।`,
    science: `Self-Determination Theory (Deci & Ryan): आंतरिक प्रेरणा (शुद्ध इच्छा से, अपने लिए कर्म करना) बाह्य प्रेरणा (पुरस्कार/भय के लिए कर्म) से बिल्कुल भिन्न तंत्रिकीय और मनोवैज्ञानिक परिणाम देती है। गीता जिस "भक्ति" का वर्णन करती है वह आंतरिक प्रेरणा का शुद्धतम रूप है — दिव्य के प्रेम से कर्म, व्यक्तिगत लाभ के लिए नहीं।`,
    lifeLesson: `कोई भी कर्म पूर्ण समर्पण के साथ — बिना व्यक्तिगत स्वार्थ, बिना फल की लालसा के — भक्ति का रूप बन जाता है। आज एक कार्य पूर्णतः उसी के लिए, अर्पण के रूप में करो। देखो कैसे ध्यान की गुणवत्ता बदल जाती है।`,
  },
  '15:1': {
    explanation: `ऊपर जड़ (ब्रह्म में) और नीचे शाखाओं (व्यक्त जगत में) वाला ब्रह्मांडीय वृक्ष अस्तित्व का गहन रूपक है। हमारा रूपों का जगत एक अतींद्रिय मूल से नीचे की ओर बढ़ता है। यह वृक्ष "अश्वत्थ" है — अनित्य, कल जैसा कभी न रहने वाला। एकमात्र स्थायी वस्तु मूल है — ब्रह्म।`,
    science: `विकासवादी जीवविज्ञान जीवन को एक वृक्ष के रूप में देखता है — सभी प्रजातियाँ एक साझा मूल से शाखाबद्ध। कैऑस थ्योरी: जटिल तंत्र इस अर्थ में "top-down" हैं कि कुछ मूलभूत नियम (मूल/अपरिवर्तनीय) अपार विविधता (शाखाएँ/पत्ते) को जन्म देते हैं। गीता का उलटा वृक्ष — जहाँ अतींद्रिय मूल है और दृश्य पत्ते — यह दर्शाता है कि व्यवस्था एक उच्चतर स्रोत से कैसे प्रवाहित होती है।`,
    lifeLesson: `जो कुछ दृश्य है — तुम्हारा करियर, संबंध, स्वास्थ्य, उपलब्धियाँ — ये शाखाएँ और पत्ते हैं। ये अदृश्य मूल से उगते हैं। मूल के साथ समय बिताओ: अपने मूल्य, अपना आंतरिक जीवन, स्रोत से अपना संबंध। गहरी जड़ों वाला वृक्ष किसी भी आँधी में टिक जाता है।`,
  },
  '15:7': {
    explanation: `एक उल्लेखनीय श्लोक: व्यक्तिगत आत्मा (जीव) कृष्ण (ब्रह्म) का शाश्वत अंश है। कोई रचना नहीं, कोई प्रतिलिपि नहीं — एक अंश। अंश और पूर्ण समान सारभूत प्रकृति साझा करते हैं। सागर और सागर की एक बूँद — दोनों जल हैं। यह अंश इन्द्रियों को अपनी ओर खींचता है — यही शरीर को अनुप्राणित करता है।`,
    science: `भौतिकी में होलोग्राफिक सिद्धांत ('t Hooft, Susskind): होलोग्राम का हर भाग पूर्ण की सूचना धारण करता है। इसी प्रकार व्यक्तिगत चेतना (अंश) अपने भीतर पूर्ण चेतना की संरचना समेटे है। यह मात्र रूपक नहीं — क्वांटम entanglement सुझाता है कि किसी तंत्र के "अंश" पूर्ण की अस्थानीय (non-local) सूचना धारण कर सकते हैं।`,
    lifeLesson: `तुम कोई पृथक प्राणी नहीं हो जिसके पास संयोगवश चेतना है। तुम चेतना ही हो, जो मनुष्य के रूप में प्रकट है — अनंत का एक अंश। यह मानने योग्य विचार नहीं, बल्कि साकार करने योग्य पहचान है। जब तुम इस पहचान से जीते हो, तब क्या बदलता है?`,
  },
  '15:15': {
    explanation: `कृष्ण सबसे अंतरंग सत्य प्रकट करते हैं: वे हर प्राणी के हृदय में उसकी बुद्धि के मूल स्रोत के रूप में स्थित हैं। स्मृति, ज्ञान, यहाँ तक कि संशय का निवारण — सब इसी आंतरिक स्रोत से प्रवाहित होते हैं। स्पष्टता का हर क्षण, समझ की हर कौंध शाब्दिक रूप से भीतर स्थित दिव्य बुद्धि की अभिव्यक्ति है।`,
    science: `स्मृति-समेकन शोध: हिप्पोकैम्पस मस्तिष्क में "स्मृति का आसन" है। पर इससे भी गहराई से — जो आत्मा स्मृतियों को समय के पार एक निरंतर कथा के रूप में जोड़े रखती है, वही रहस्य गीता इंगित करती है। बिना एक स्थिर "आंतरिक साक्षी" (मैं-बोध) के, स्मृतियाँ सुसंगति के बिना मात्र आँकड़े होतीं — जैसे ऐसी फ़ाइलें जिन्हें खोलने वाला कोई उपयोगकर्ता न हो।`,
    lifeLesson: `अगली बार जब तुम्हें कोई सच्ची अंतर्दृष्टि या स्पष्टता का क्षण मिले — रुको। तुम्हारे भीतर कुछ अभी-अभी जान गया। वह जानना तुम्हारी व्यक्तिगत उपलब्धि नहीं; वह तुम्हारे हृदय में स्थित दिव्य बुद्धि है। इन जानने के क्षणों के प्रति कृतज्ञता भीतर के ईश्वर को पहचानने का एक रूप है।`,
  },
  '16:1': {
    explanation: `कृष्ण छब्बीस दैवी गुणों की सूची देते हैं जो "दैवी सम्पत्" का निर्माण करते हैं। यह गीता का सबसे व्यापक चरित्र-चित्र है — आदर्श मनुष्य। ये आदेश नहीं, बल्कि उन स्वाभाविक गुणों का वर्णन हैं जो सत्य के अनुरूप जीने पर स्वतः प्रकट होते हैं। अभय (निर्भयता) सूची में सर्वप्रथम है — यह वह मूलभूत गुण है जिससे शेष सभी प्रवाहित होते हैं।`,
    science: `सकारात्मक मनोविज्ञान के Character Strengths (VIA Institute, Seligman & Peterson, 2004): सभी संस्कृतियों में पहचाने गए 24 सार्वभौमिक चरित्र-बल। अभय (साहस), सत्यनिष्ठा (सरलता), उदारता (दान) और आत्म-नियमन (दम) निरंतर उन गुणों में हैं जो समृद्धि से सर्वाधिक सहसम्बद्ध हैं। 2500 वर्ष पूर्व लिखी गीता की सूची उससे निकटता से मेल खाती है जिसे अनुभवजन्य शोध सार्वभौमिक सद्गुण मानता है।`,
    lifeLesson: `इन छब्बीस गुणों में से वह एक पहचानो जो तुममें अभी सबसे प्रबल है — और वह जो सबसे अनुपस्थित। प्रबल तुम्हारा मंच है; अनुपस्थित तुम्हारी वृद्धि का किनारा। आज उस अनुपस्थित गुण की ओर एक छोटा कदम बढ़ाओ।`,
  },
  '16:21': {
    explanation: `यहाँ "नरक" मृत्यु के बाद का कोई स्थान नहीं, बल्कि इसी जीवन की एक अवस्था है — काम, क्रोध और लोभ से चालित जीवन का नरक। ये तीनों एक स्व-प्रबलित चक्र बनाते हैं: काम (जो नहीं है उसकी लालसा) → रुकावट पर कुंठा → क्रोध → और अधिक की चाह → लोभ। तीनों में से किसी एक को तोड़ना तीनों को कमजोर करता है।`,
    science: `व्यवहार-तंत्रिका-विज्ञान: ये तीनों विशिष्ट तंत्रिका-परिपथों से मेल खाते हैं। काम/लालसा = मेसोलिम्बिक डोपामिन मार्ग (पुरस्कार-खोज)। क्रोध = एमिग्डाला-हाइपोथैलेमिक खतरा-प्रतिक्रिया। लोभ = प्रीफ्रंटल-पुरस्कार परिपथ का युग्मन। आवेग-नियंत्रण पर शोध (Baumeister): ये तीनों अधिकांश विनाशकारी मानव व्यवहार के प्रमुख चालक हैं। गीता मनोविज्ञान से सहस्राब्दियों पूर्व इन तीन मूल कारणों को पहचान लेती है।`,
    lifeLesson: `जब दुःख अनुभव हो, उसे मूल तक खोजो: क्या यह अपूर्ण इच्छा (काम) में जड़ है, अवरुद्ध इच्छा के क्रोध (क्रोध) में, या पर्याप्त न होने के भय (लोभ) में? मूल का नामकरण ही उससे मुक्ति का पहला कदम है। एक क्षण का ईमानदार आत्म-निरीक्षण इस चक्र को तोड़ सकता है।`,
  },
  '17:3': {
    explanation: `गीता के सर्वाधिक मनोवैज्ञानिक रूप से सटीक श्लोकों में से एक। श्रद्धा का अनुवाद प्रायः "faith" किया जाता है, पर इसका अर्थ अधिक समृद्ध है — इस बारे में किसी की गहनतम धारणाएँ कि क्या वास्तविक है, क्या संभव है, और किसके लिए जीना सार्थक है। तुम मूलतः जो मानते हो (सचेत रूप से या नहीं) वही सब कुछ आकार देता है — तुम क्या खोजते हो, कैसे कर्म करते हो, क्या बनते हो। "जैसी श्रद्धा, वैसा पुरुष।"`,
    science: `स्व-पूर्तिकारी भविष्यवाणी शोध (Rosenthal & Jacobson, Pygmalion प्रभाव): शिक्षक की अपेक्षाएँ विद्यार्थी के परिणामों को मापने योग्य रूप से आकार देती हैं। Carol Dweck का growth बनाम fixed mindset शोध: अपनी परिवर्तन-क्षमता के बारे में मूलभूत मान्यताएँ अत्यंत भिन्न जीवन-दिशाएँ उत्पन्न करती हैं। गीता का "श्रद्धामयोऽयं पुरुषः" उसी का सबसे प्राचीन और संक्षिप्त कथन है जिसे संज्ञानात्मक मनोविज्ञान को सिद्ध करने में दशकों लगे।`,
    lifeLesson: `तुम अपने बारे में, संभव के बारे में, और जिसके तुम योग्य हो उसके बारे में मूलतः क्या मानते हो? ये गहरी मान्यताएँ — तुम्हारी श्रद्धा — अभी तुम्हारा जीवन रच रही हैं। आज जाँचने योग्य एक मान्यता: "क्या मेरे लिए परिवर्तन संभव है?" इस प्रश्न का तुम्हारा उत्तर शेष सब कुछ आकार देता है।`,
  },
  '17:17': {
    explanation: `अनुशासन का उच्चतम रूप व्यक्तिगत पुरस्कार की अपेक्षा के बिना अभ्यास किया जाता है। जो व्यक्ति व्यायाम, ध्यान, अध्ययन और सेवा करता है — अहं-तृप्ति के लिए नहीं, बल्कि इसलिए कि यह उचित है — वह सात्त्विक तप करता है। यह अध्याय 17 और अध्याय 2 (कर्मयोग) का मिलन-बिंदु है: फल की आसक्ति के बिना कर्म।`,
    science: `Self-Determination Theory (Deci & Ryan): स्वायत्त प्रेरणा (किसी कार्य को इसलिए करना कि वह स्वयं में सार्थक है, बिना बाहरी दबाव या पुरस्कार-अपेक्षा के) सबसे गहरा और टिकाऊ व्यवहार-परिवर्तन, सर्वाधिक कल्याण और उच्चतम प्रदर्शन उत्पन्न करती है। "सात्त्विक तप" ठीक इसी स्वायत्त, अनासक्त अभ्यास-विधि का वर्णन करता है।`,
    lifeLesson: `क्या तुम्हारी आध्यात्मिक साधना, व्यायाम, अध्ययन या अनुशासन सच्चे आंतरिक अनुरूपण से प्रेरित है — या चिंता, तुलना या प्रदर्शन से? प्रेरणा की गुणवत्ता फल को आकार देती है। आज एक साधना पूर्णतः उसके अंतर्निहित मूल्य के लिए, बिना किसी स्वार्थ के करो।`,
  },
  '18:66': {
    explanation: `यह गीता का चरम संदेश है — सर्वोत्तम रहस्योपनिषद्। कृष्ण पूर्ण शरणागति (समर्पण) मांगते हैं: सभी धर्मों को त्यागो और केवल मुझमें शरण लो। आश्वासन है — जो केवल उन्हीं की शरण लेता है, उसे वे सभी पापों से मुक्त करते हैं, शोक नहीं होगा। यह निष्क्रियता का आदेश नहीं — यह अहंकार का त्याग है। "सर्वधर्मान् परित्यज्य" का अर्थ है स्वार्थ-जनित धर्मों को छोड़ना, और ईश्वर-समर्पित धर्म में जीना। यही गीता का सर्वोच्च संदेश है।`,
    science: `"radical acceptance" (आमूल स्वीकृति) पर मनोवैज्ञानिक शोध (Tara Brach, Marsha Linehan): जब व्यक्ति जो है उसके प्रति प्रतिरोध पूरी तरह छोड़ देता है, तो विरोधाभासी रूप से उसे उसे बदलने की मानसिक स्पष्टता मिल जाती है। समर्पण निष्क्रियता नहीं — यह विश्वास का सर्वाधिक सक्रिय रूप है।`,
    lifeLesson: `जब तुम अपना सर्वोत्तम कर चुको और फिर भी भय हो, तो छोड़ दो। अति-विश्लेषण पंगु बनाता है; विश्वास मुक्त करता है। सबसे गहरी शक्ति है — नियंत्रण को अपने भीतर की उच्चतर बुद्धि को सौंपने का साहस।`,
  },
  '18:78': {
    explanation: `गीता का अंतिम श्लोक एक आश्वासन है। जहाँ कृष्ण (ज्ञान, योग, आध्यात्मिक शक्ति) और अर्जुन (कर्म, योद्धा, भौतिक शक्ति) एक हों, वहाँ विजय, समृद्धि और मंगल निश्चित है। यह ज्ञान और कर्म के संयोग का सूत्र है — केवल ज्ञान या केवल कर्म पर्याप्त नहीं, दोनों का मिलन ही उत्कृष्टता देता है। यही गीता का अंतिम निष्कर्ष है।`,
    science: `Systems thinking: जब किसी भी तंत्र में आदर्श रणनीति (कृष्ण = ज्ञान) और आदर्श क्रियान्वयन (अर्जुन = कर्म) का मिलन होता है, तब परिणाम optimal होते हैं। यह "ज्ञान + कर्म = उत्कृष्टता" का सार्वभौमिक सूत्र है, जो आधुनिक management theory, sports science और organisational psychology में प्रमाणित है।`,
    lifeLesson: `ज्ञान और कर्म का संयोग — यही गीता का अंतिम संदेश है। केवल जानना काफी नहीं, केवल करना काफी नहीं। जब दोनों एक साथ हों — तभी जीवन में विजय है।`,
  },
  '1:2': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '1:3': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '1:4': {
    explanation: `हे केशव! मैं अपशकुन ही देख रहा हूँ। युद्ध में स्वजनों को मारने में मुझे कोई कल्याण नहीं दिखता।`,
  },
  '1:5': {
    explanation: `यदि धार्तराष्ट्र शस्त्र-पाणि होकर युद्ध में मुझ अप्रतिकार करने वाले को मार दें, तो यह मेरे लिए अधिक कल्याणकारक होगा।`,
  },
  '1:6': {
    explanation: `संजय बोले — इस प्रकार कहकर, शोक से व्याकुल मन वाले अर्जुन ने रणभूमि में अपने बाण और धनुष छोड़कर रथ के पिछले भाग में बैठ गए।`,
  },
  '1:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '1:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '1:9': {
    explanation: `।।1.9।। इनके अतिरिक्त बहुत-से शूरवीर हैं, जिन्होंने मेरे लिये अपने जीने की इच्छा का भी त्याग कर दिया है और जो अनेक प्रकार के शस्त्र-अस्त्रों को चलानेवाले हैं तथा जो सब-के-सब युद्धकला में अत्यन्त चतुर हैं।
 `,
  },
  '1:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '1:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '1:12': {
    explanation: `।।1.12।। दुर्योधन के हृदय में हर्ष उत्पन्न करते हुए कुरुवृद्ध प्रभावशाली पितामह भीष्म ने सिंह के समान गरज कर जोर से शंख बजाया।
 `,
  },
  '1:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '1:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '1:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '1:16': {
    explanation: `।।1.16।। कुन्तीपुत्र राजा युधिष्ठिर ने अनन्तविजय नामक शंख बजाया तथा नकुल और सहदेव ने सुघोष और मणिपुष्पक नामक शंख बजाये।
 `,
  },
  '1:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '1:18': {
    explanation: `।।1.17 -- 1.18।। हे राजन्! श्रेष्ठ धनुषवाले काशिराज और महारथी शिखण्डी तथा धृष्टद्युम्न एवं राजा विराट और अजेय सात्यकि, राजा द्रुपद और द्रौपदी के पाँचों पुत्र तथा लम्बी-लम्बी भुजाओंवाले सुभद्रा-पुत्र अभिमन्यु - इन सभी ने सब ओर से अलग-अलग (अपने-अपने) शंख बजाये।
 `,
  },
  '1:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '1:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '1:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '1:23': {
    explanation: `।।1.23।। दुष्टबुद्धि दुर्योधन का युद्ध में प्रिय करने की इच्छावाले जो ये राजालोग इस सेना में आये हुए हैं, युद्ध करने को उतावले हुए इन सबको मैं देख लूँ।
 `,
  },
  '1:24': {
    explanation: `।।1.24 -- 1.25।। संजय बोले - हे भरतवंशी राजन्! निद्राविजयी अर्जुन के द्वारा इस तरह कहने पर अन्तर्यामी भगवान् श्रीकृष्ण ने दोनों सेनाओं के मध्यभाग में पितामह भीष्म और आचार्य द्रोण के सामने तथा सम्पूर्ण राजाओं के सामने श्रेष्ठ रथ को खड़ा करके इस तरह कहा कि 'हे पार्थ! इन इकट्ठे हुए कुरुवंशियोंको देख'।
 `,
  },
  '1:25': {
    explanation: `।।1.24 -- 1.25।। संजय बोले - हे भरतवंशी राजन्! निद्राविजयी अर्जुन के द्वारा इस तरह कहने पर अन्तर्यामी भगवान् श्रीकृष्ण ने दोनों सेनाओं के मध्यभाग में पितामह भीष्म और आचार्य द्रोण के सामने तथा सम्पूर्ण राजाओं के सामने श्रेष्ठ रथको खड़ा करके इस तरह कहा कि 'हे पार्थ! इन इकट्ठे हुए कुरुवंशियोंको देख'।
 `,
  },
  '1:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '1:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '1:29': {
    explanation: `।।1.28 -- 1.30।। अर्जुन बोले - हे कृष्ण! युद्ध की इच्छावाले इस कुटुम्ब-समुदाय को अपने सामने उपस्थित देखकर मेरे अङ्ग शिथिल हो रहे हैं और मुख सूख रहा है तथा मेरे शरीर में कँपकँपी आ रही है एवं रोंगटे खड़े हो रहे हैं। हाथ से गाण्डीव धनुष गिर रहा है और त्वचा भी जल रही है। मेरा मन भ्रमित-सा हो रहा है और मैं खड़े रहने में भी असमर्थ हो रहा हूँ।
 `,
  },
  '1:32': {
    explanation: `आकाश में एक साथ हज़ार सूर्य उदय हों तो जो प्रकाश हो, वह उस महात्मा (विश्वरूप) के तेज के समान होगा।`,
  },
  '1:33': {
    explanation: `।।1.33।। जिनके लिये हमारी राज्य, भोग और सुखकी इच्छा है, वे ही ये सब अपने प्राणों की और धन की आशा का त्याग करके युद्ध में खड़े हैं।
 `,
  },
  '1:34': {
    explanation: `हे पार्थ! जो तुमने देखा वह मेरी योगमाया से प्रकट किया गया था। अब मैं तुम्हें अपना शाश्वत रूप बताता हूँ।`,
  },
  '1:35': {
    explanation: `अपने स्वधर्म में मरना भला है, चाहे वह अपूर्ण हो; परधर्म को अच्छी तरह से करना भयावह है।`,
  },
  '1:36': {
    explanation: `।।1.36।। हे जनार्दन! इन धृतराष्ट्र-सम्बन्धियों को मारकर हमलोगों को क्या प्रसन्नता होगी? इन आततायियों को मारने से तो हमें पाप ही लगेगा।
 `,
  },
  '1:37': {
    explanation: `।।1.37।। इसलिये अपने बान्धव इन धृतराष्ट्र-सम्बन्धियों को मारने के लिये हम योग्य नहीं हैं; क्योंकि हे माधव! अपने कुटुम्बियों को मारकर हम कैसे सुखी होंगे?
 `,
  },
  '1:38': {
    explanation: `सुख-दुःख, लाभ-हानि और जय-पराजय को समान करके तब युद्ध के लिए तैयार हो। इस प्रकार तुम पाप नहीं प्राप्त करोगे।`,
  },
  '1:39': {
    explanation: `।।1.38 -- 1.39।। यद्यपि लोभ के कारण जिनका विवेक-विचार लुप्त हो गया है, ऐसे ये (दुर्योधन आदि) कुल का नाश करने से होनेवाले दोष को और मित्रों के साथ द्वेष करने से होनेवाले पाप को नहीं देखते, (तो भी) हे जनार्दन! कुल का नाश करने से होनेवाले दोष को ठीक-ठीक जाननेवाले हमलोग इस पाप से निवृत्त होनेका विचार क्यों न करें?
 `,
  },
  '1:40': {
    explanation: `।।1.40।। कुल का क्षय होने पर सदा से चलते आये कुलधर्म नष्ट हो जाते हैं और धर्म का नाश होनेपर (बचे हुए) सम्पूर्ण कुल को अधर्म दबा लेता है।
 `,
  },
  '1:41': {
    explanation: `।।1.41।। हे कृष्ण! अधर्म के अधिक बढ़ जाने से कुल की स्त्रियाँ दूषित हो जाती हैं; (और) हे वार्ष्णेय! स्त्रियों के दूषित होने पर वर्णसंकर पैदा हो जाते हैं।
 `,
  },
  '1:42': {
    explanation: `जो-जो आचरण श्रेष्ठ पुरुष करता है, अन्य लोग भी वही करते हैं। वह जो प्रमाण स्थापित करता है, संसार उसी का अनुसरण करता है।`,
  },
  '1:43': {
    explanation: `।।1.43।। इन वर्णसंकर पैदा करनेवाले दोषोंसे कुलघातियों के सदा से चलते आये कुलधर्म और जातिधर्म नष्ट हो जाते हैं।
 `,
  },
  '1:44': {
    explanation: `।।1.44।। हे जनार्दन! जिनके कुलधर्म नष्ट हो जाते हैं, उन मनुष्यों का बहुत काल तक नरकों में वापस होता है, ऐसा हम सुनते आये हैं।
 `,
  },
  '1:45': {
    explanation: `।।1.45।। यह बड़े आश्चर्य और खेद की बात है कि हमलोग बड़ा भारी पाप करने का निश्चय कर बैठे हैं, जो कि राज्य और सुख के लोभ से अपने स्वजनों को मारने के लिये तैयार हो गये हैं!
 `,
  },
  '2:1': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '2:2': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '2:3': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '2:4': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '2:5': {
    explanation: `आत्मा न तो कभी जन्म लेती है और न ही मरती है। वह एक बार उत्पन्न होने पर फिर होने वाली भी नहीं है। यह अजन्मा, नित्य, शाश्वत और पुरातन है — शरीर के नाश होने पर भी इसका नाश नहीं होता।`,
  },
  '2:6': {
    explanation: `सुख-दुःख, लाभ-हानि और जय-पराजय को समान करके तब युद्ध के लिए तैयार हो। इस प्रकार तुम पाप नहीं प्राप्त करोगे।`,
  },
  '2:7': {
    explanation: `तुम्हारा अधिकार केवल कर्म करने में है, फल में कभी नहीं। न तो कर्म के फल का कारण बनो, और न ही कर्म न करने में आसक्त हो।`,
  },
  '2:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '2:9': {
    explanation: `।।2.9।। संजय बोले - हे शत्रुतापन धृतराष्ट्र! ऐसा कहकर निद्राको जीतनेवाले अर्जुन अन्तर्यामी भगवान् गोविन्दसे 'मैं युद्ध नहीं करूँगा' ऐसा साफ-साफ कहकर चुप हो गये।
 `,
  },
  '2:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '2:12': {
    explanation: `।।2.12।। किसी कालमें मैं नहीं था और तू नहीं था तथा ये राजालोग नहीं थे, यह बात भी नहीं है; और इसके बाद (भविष्य में) मैं, तू और राजलोग - हम सभी नहीं रहेंगे, यह बात भी नहीं है।
 `,
  },
  '2:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '2:16': {
    explanation: `।।2.16।। (टिप्पणी प0 55) असत् का तो भाव (सत्ता) विद्यमान नहीं है और सत् का अभाव विद्यमान नहीं है, तत्त्वदर्शी महापुरुषोंने इन दोनोंका ही अन्त अर्थात् तत्त्व देखा है।
 `,
  },
  '2:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '2:18': {
    explanation: `।।2.18।। अविनाशी, अप्रमेय और नित्य रहनेवाले इस शरीरी के ये देह अन्तवाले कहे गये हैं। इसलिये हे अर्जुन! तुम युद्ध करो।
 `,
  },
  '2:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '2:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '2:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '2:23': {
    explanation: `।।2.23।। शस्त्र इस शरीरीको काट नहीं सकते, अग्नि इसको जला नहीं सकती, जल इसको गीला नहीं कर सकता और वायु इसको सुखा नहीं सकती।
 `,
  },
  '2:24': {
    explanation: `।।2.24।। यह शरीरी काटा नहीं जा सकता, यह जलाया नहीं जा सकता, यह गीला नहीं किया जा सकता और यह सुखाया भी नहीं जा सकता। कारण कि यह नित्य रहनेवाला सबमें परिपूर्ण, अचल, स्थिर स्वभाववाला और अनादि है।
 `,
  },
  '2:25': {
    explanation: `।।2.25।। यह देही प्रत्यक्ष नहीं दीखता, यह चिन्तनका विषय नहीं है और यह निर्विकार कहा जाता है। अतः इस देहीको ऐसा जानकर शोक नहीं करना चाहिये।
 `,
  },
  '2:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '2:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '2:29': {
    explanation: `।।2.29।। कोई इस शरीरीको आश्चर्यकी तरह देखता है और वैसे ही अन्य कोई इसका आश्चर्यकी तरह वर्णन करता है तथा अन्य कोई इसको आश्चर्यकी तरह सुनता है; और इसको सुनकर भी कोई नहीं जानता। अर्थात यह शरीरी दुर्विज्ञेय है। `,
  },
  '2:30': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '2:31': {
    explanation: `हे केशव! मैं अपशकुन ही देख रहा हूँ। युद्ध में स्वजनों को मारने में मुझे कोई कल्याण नहीं दिखता।`,
  },
  '2:32': {
    explanation: `आकाश में एक साथ हज़ार सूर्य उदय हों तो जो प्रकाश हो, वह उस महात्मा (विश्वरूप) के तेज के समान होगा।`,
  },
  '2:33': {
    explanation: `।।2.33।। अब अगर तू यह धर्ममय युद्ध नहीं करेगा,  तो अपने धर्म और कीर्तिका त्याग करके पापको प्राप्त होगा।
 `,
  },
  '2:34': {
    explanation: `हे पार्थ! जो तुमने देखा वह मेरी योगमाया से प्रकट किया गया था। अब मैं तुम्हें अपना शाश्वत रूप बताता हूँ।`,
  },
  '2:35': {
    explanation: `अपने स्वधर्म में मरना भला है, चाहे वह अपूर्ण हो; परधर्म को अच्छी तरह से करना भयावह है।`,
  },
  '2:36': {
    explanation: `।।2.36।। तेरे शत्रुलोग तेरी सार्मथ्यकी निन्दा करते हुए न कहनेयोग्य बहुत-से वचन भी कहेंगे। उससे बढ़कर और दुःखकी बात क्या होगी?
 `,
  },
  '2:37': {
    explanation: `।।2.37।। अगर युद्धमें तू मारा जायगा तो तुझे स्वर्गकी प्राप्ति होगी और अगर युद्धमें तू जीत जायगा तो पृथ्वीका राज्य भोगेगा। अतः हे कुन्तीनन्दन! तू युद्धके लिये निश्चय करके खड़ा हो जा।
 `,
  },
  '2:39': {
    explanation: `।।2.39।। हे पार्थ! यह समबुद्धि तेरे लिए पहले सांख्ययोगमें कही गयी, अब तू इसको कर्मयोगके विषयमें सुन; जिस समबुद्धिसे युक्त हुआ तू कर्मबन्धनका त्याग कर देगा।
 `,
  },
  '2:40': {
    explanation: `।।2.40।। मनुष्यलोकमें इस समबुद्धिरूप धर्मके आरम्भका नाश नहीं होता, इसके अनुष्ठानका उलटा फल भी नहीं होता और इसका थोड़ासा भी अनुष्ठान (जन्म-मरणरूप) महान् भयसे रक्षा कर लेता है।
 `,
  },
  '2:41': {
    explanation: `।।2.41।। हे कुरुनन्दन! इस समबुद्धिकी प्राप्तिके विषयमें व्यवसायात्मिका बुद्धि एक ही होती है। अव्यवसायी मनुष्योंकी बुद्धियाँ अनन्त और बहुशाखाओंवाली ही होती हैं।
 `,
  },
  '2:42': {
    explanation: `जो-जो आचरण श्रेष्ठ पुरुष करता है, अन्य लोग भी वही करते हैं। वह जो प्रमाण स्थापित करता है, संसार उसी का अनुसरण करता है।`,
  },
  '2:43': {
    explanation: `।।2.42 -- 2.43।। हे पृथानन्दन ! जो कामनाओंमें तन्मय हो रहे हैं, स्वर्गको ही श्रेष्ठ माननेवाले हैं, वेदोंमें कहे हुए सकाम कर्मोंमें प्रीति रखनेवाले हैं, भोगोंके सिवाय और कुछ है ही नहीं - ऐसा कहनेवाले हैं, वे अविवेकी मनुष्य इस प्रकारकी जिस पुष्पित (दिखाऊ शोभायुक्त) वाणीको कहा करते हैं, जो कि जन्मरूपी कर्मफलको देनेवाली है तथा भोग और ऐश्वर्यकी प्राप्तिके लिये बहुतसी क्रियाओंका वर्णन करनेवाली है।
 `,
  },
  '2:44': {
    explanation: `।।2.44।। उस पुष्पित वाणीसे जिसका अन्तःकरण हर लिया गया है अर्थात् भोगोंकी तरफ खिंच गया है और जो भोग तथा ऐश्वर्यमें अत्यन्त आसक्त हैं, उन मनुष्योंकी परमात्मामें निश्चयात्मिका बुद्धि नहीं होती।
 `,
  },
  '2:45': {
    explanation: `।।2.45।। वेद तीनों गुणोंके कार्यका ही वर्णन करनेवाले हैं; हे अर्जुन! तू तीनों गुणोंसे रहित हो जा, निर्द्वन्द्व हो जा, निरन्तर नित्य वस्तु परमात्मा में स्थित हो जा, योगक्षेमकी चाहना भी मत रख और परमात्मपरायण हो जा।
 `,
  },
  '2:46': {
    explanation: `यदि धार्तराष्ट्र शस्त्र-पाणि होकर युद्ध में मुझ अप्रतिकार करने वाले को मार दें, तो यह मेरे लिए अधिक कल्याणकारक होगा।`,
  },
  '2:48': {
    explanation: `।।2.48।। हे धनञ्जय ! तू आसक्तिका त्याग करके सिद्धि-असिद्धिमें सम होकर योगमें स्थित हुआ कर्मोंको कर; क्योंकि समत्व ही योग कहा जाता है।
 `,
  },
  '2:49': {
    explanation: `।।2.49।। बुद्धियोग-(समता) की अपेक्षा सकामकर्म दूरसे (अत्यन्त) ही निकृष्ट है। अतः हे धनञ्जय ! तू बुद्धि (समता) का आश्रय ले; क्योंकि फलके हेतु बननेवाले अत्यन्त दीन हैं।
 `,
  },
  '2:50': {
    explanation: `।।2.50।। बुद्धि-(समता) से युक्त मनुष्य यहाँ जीवित अवस्थामें ही पुण्य और पाप दोनोंका त्याग कर देता है। अतः तू योग-(समता-) में लग जा, क्योंकि योग ही कर्मोंमें कुशलता है।
 `,
  },
  '2:51': {
    explanation: `।।2.51।। समतायुक्त मनीषी साधक कर्मजन्य फलका त्याग करके जन्मरूप बन्धनसे मुक्त होकर निर्विकार पदको प्राप्त हो जाते हैं।
 `,
  },
  '2:52': {
    explanation: `।।2.52।। जिस समय तेरी बुद्धि मोहरूपी दलदलको तर जायगी, उसी समय तू सुने हुए और सुननेमें आनेवाले भोगोंसे वैराग्यको प्राप्त हो जायगा।
 `,
  },
  '2:53': {
    explanation: `।।2.53।। जिस कालमें शास्त्रीय मतभेदोंसे विचलित हुई तेरी बुद्धि निश्चल हो जायगी और परमात्मामें अचल हो जायगी, उस कालमें तू योगको प्राप्त हो जायगा।
 `,
  },
  '2:54': {
    explanation: `।।2.54।। अर्जुन बोले - हे केशव ! परमात्मामें स्थित स्थिर बुद्धिवाले मनुष्यके क्या लक्षण होते हैं? वह स्थिर बुद्धिवाला मनुष्य कैसे बोलता है, कैसे बैठता है और कैसे चलता है?
 `,
  },
  '2:55': {
    explanation: `।।2.55।। श्रीभगवान् बोले - हे पृथानन्दन ! जिस कालमें साधक मनोगत सम्पूर्ण कामनाओंका अच्छी तरह त्याग कर देता है और अपने-आपसे अपने-आपमें ही सन्तुष्ट रहता है, उस कालमें वह स्थितप्रज्ञ कहा जाता है।
 `,
  },
  '2:56': {
    explanation: `।।2.56।। दुःखोंकी प्राप्ति होनेपर जिसके मनमें उद्वेग नहीं होता और सुखोंकी प्राप्ति होनेपर जिसके मनमें स्पृहा नहीं होती तथा जो राग, भय और क्रोधसे सर्वथा रहित हो गया है, वह मननशील मनुष्य स्थिरबुद्धि कहा जाता है।
 `,
  },
  '2:57': {
    explanation: `।।2.57।। सब जगह आसक्तिरहित हुआ जो मनुष्य उस-उस शुभ-अशुभको प्राप्त करके न तो अभिनन्दित होता है और न द्वेष करता है, उसकी बुद्धि प्रतिष्ठित है।
 `,
  },
  '2:58': {
    explanation: `।।2.58।। जिस तरह कछुआ अपने अङ्गोंको सब ओरसे समेट लेता है, ऐसे ही जिस कालमें यह कर्मयोगी इन्द्रियोंके विषयोंसे इन्द्रियोंको सब प्रकारसे समेट लेता (हटा लेता) है, तब उसकी बुद्धि प्रतिष्ठित हो जाती है।
 `,
  },
  '2:59': {
    explanation: `।।2.59।। निराहारी (इन्द्रियोंको विषयोंसे हटानेवाले) मनुष्यके भी विषय तो निवृत्त हो जाते हैं, पर रस निवृत्त नहीं होता। परन्तु इस स्थितप्रज्ञ मनुष्यका तो रस भी परमात्मतत्त्वका अनुभव होनेसे निवृत्त हो जाता है।
 `,
  },
  '2:60': {
    explanation: `।।2.60।। हे कुन्तीनन्दन! (रसबुद्धि रहनेसे) यत्न करते हुए विद्वान् मनुष्यकी भी प्रमथनशील इन्द्रियाँ उसके मनको बलपूर्वक हर लेती हैं।
 `,
  },
  '2:61': {
    explanation: `।।2.61।। कर्मयोगी साधक उन सम्पूर्ण इन्द्रियोंको वशमें करके मेरे परायण होकर बैठे; क्योंकि जिसकी इन्द्रियाँ वशमें हैं, उसकी बुद्धि प्रतिष्ठित है।
 `,
  },
  '2:62': {
    explanation: `।।2.62 -- 2.63।। विषयोंका चिन्तन करनेवाले मनुष्यकी उन विषयोंमें आसक्ति पैदा हो जाती है। आसक्तिसे कामना पैदा होती है। कामनासे क्रोध पैदा होता है। क्रोध होनेपर सम्मोह (मूढ़भाव) हो जाता है। सम्मोहसे स्मृति भ्रष्ट हो जाती है। स्मृति भ्रष्ट होनेपर बुद्धिका नाश हो जाता है। बुद्धिका नाश होनेपर मनुष्यका पतन हो जाता है।
 `,
  },
  '2:63': {
    explanation: `।।2.62 -- 2.63।। विषयोंका चिन्तन करनेवाले मनुष्यकी उन विषयोंमें आसक्ति पैदा हो जाती है। आसक्तिसे कामना पैदा होती है। कामनासे क्रोध पैदा होता है। क्रोध होनेपर सम्मोह (मूढ़भाव) हो जाता है। सम्मोहसे स्मृति भ्रष्ट हो जाती है। स्मृति भ्रष्ट होनेपर बुद्धिका नाश हो जाता है। बुद्धिका नाश होनेपर मनुष्यका पतन हो जाता है।
 `,
  },
  '2:64': {
    explanation: `।।2.64 -- 2.65।। वशीभूत अन्तःकरणवाला कर्मयोगी साधक रागद्वेषसे रहित अपने वशमें की हुई इन्द्रियोंके द्वारा विषयोंका सेवन करता हुआ अन्तःकरणकी निर्मलता को प्राप्त हो जाता है। निर्मलता प्राप्त होनेपर साधकके सम्पूर्ण दुःखोंका नाश हो जाता है और ऐसे शुद्ध चित्तवाले साधककी बुद्धि निःसन्देह बहुत जल्दी परमात्मामें स्थिर हो जाती है।
 `,
  },
  '2:65': {
    explanation: `।।2.64 -- 2.65।। वशीभूत अन्तःकरणवाला कर्मयोगी साधक रागद्वेषसे रहित अपने वशमें की हुई इन्द्रियोंके द्वारा विषयोंका सेवन करता हुआ अन्तःकरणकी निर्मलता को प्राप्त हो जाता है। निर्मलता प्राप्त होनेपर साधकके सम्पूर्ण दुःखोंका नाश हो जाता है और ऐसे शुद्ध चित्तवाले साधककी बुद्धि निःसन्देह बहुत जल्दी परमात्मामें स्थिर हो जाती है।
 `,
  },
  '2:66': {
    explanation: `सभी धर्मों (कर्तव्यों) को छोड़कर मेरी ही शरण में आओ। मैं तुम्हें सम्पूर्ण पापों से मुक्त कर दूँगा, तुम शोक न करो।`,
  },
  '2:67': {
    explanation: `।।2.67।। अपने-अपने विषयोंमें विचरती हुई इन्द्रियोंमेंसे एक ही इन्द्रिय जिस मनको अपना अनुगामी बना लेती है, वह अकेला मन जलमें नौकाको वायुकी तरह इसकी बुद्धिको हर लेता है।
 `,
  },
  '2:68': {
    explanation: `।।2.68।। इसलिये हे महाबाहो ! जिस मनुष्यकी इन्द्रियाँ इन्द्रियोंके विषयोंसे सर्वथा निगृहीत (वशमें की हुई) हैं, उसकी बुद्धि स्थिर है।
 `,
  },
  '2:69': {
    explanation: `।।2.69।। सम्पूर्ण प्राणियों की जो रात (परमात्मासे विमुखता) है, उसमें संयमी मनुष्य जागता है, और जिसमें सब प्राणी जागते हैं (भोग और संग्रहमें लगे रहते हैं), वह तत्त्वको जाननेवाले मुनिकी दृष्टिमें रात है।
 `,
  },
  '2:70': {
    explanation: `।।2.70।। जैसे सम्पूर्ण नदियोंका जल चारों ओरसे जलद्वारा परिपूर्ण समुद्रमें आकर मिलता है, पर समुद्र अपनी मर्यादामें अचल प्रतिष्ठित रहता है ऐसे ही सम्पूर्ण भोग-पदार्थ जिस संयमी मनुष्य को विकार उत्पन्न किये बिना ही उसको प्राप्त होते हैं, वही मनुष्य परमशान्तिको प्राप्त होता है, भोगोंकी कामनावाला नहीं।
 `,
  },
  '2:71': {
    explanation: `।।2.71।। जो मनुष्य सम्पूर्ण कामनाओंका त्याग करके स्पृहारहित, ममतारहित और अहंकाररहित होकर आचरण करता है, वह शान्तिको प्राप्त होता है।
 `,
  },
  '2:72': {
    explanation: `।।2.72।। हे पृथानन्दन ! यह ब्राह्मी स्थिति है। इसको प्राप्त होकर कभी कोई मोहित नहीं होता। इस स्थितिमें यदि अन्तकालमें भी स्थित हो जाय, तो निर्वाण (शान्त) ब्रह्मकी प्राप्ति हो जाती है।
 `,
  },
  '3:1': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '3:2': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '3:3': {
    explanation: `अपने स्वधर्म में मरना भला है, चाहे वह अपूर्ण हो; परधर्म को अच्छी तरह से करना भयावह है।`,
  },
  '3:4': {
    explanation: `जो-जो आचरण श्रेष्ठ पुरुष करता है, अन्य लोग भी वही करते हैं। वह जो प्रमाण स्थापित करता है, संसार उसी का अनुसरण करता है।`,
  },
  '3:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '3:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '3:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '3:9': {
    explanation: `।।3.9।। यज्ञ (कर्तव्यपालन) के लिये किये जानेवाले कर्मोंसे अन्यत्र (अपने लिये किये जानेवाले) कर्मोंमें लगा हुआ यह मनुष्य-समुदाय कर्मोंसे बँधता है, इसलिये हे कुन्तीनन्दन ! तू आसक्ति-रहित होकर उस यज्ञके लिये ही कर्तव्य-कर्म कर। `,
  },
  '3:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '3:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '3:12': {
    explanation: `।।3.12।। यज्ञसे भावित (पुष्ट) हुए देवता भी तुमलोगोंको (बिना माँगे ही) कर्तव्य-पालनकी आवश्यक सामग्री देते रहेंगे। इस प्रकार उन देवताओंसे प्राप्त हुई सामग्रीको दूसरोंकी सेवामें लगाये बिना जो मनुष्य स्वयं ही उसका उपभोग करता है, वह चोर ही है। `,
  },
  '3:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '3:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '3:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '3:16': {
    explanation: `।।3.16।। हे पार्थ! जो मनुष्य इस लोकमें इस प्रकार परम्परासे प्रचलित सृष्टिचक्रके अनुसार नहीं चलता, वह इन्द्रियोंके द्वारा भोगोंमें रमण करनेवाला अघायु (पापमय जीवन बितानेवाला) मनुष्य संसारमें व्यर्थ ही जीता है। `,
  },
  '3:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '3:18': {
    explanation: `।।3.18।। उस (कर्मयोगसे सिद्ध हुए) महापुरुषका इस संसारमें न तो कर्म करनेसे कोई प्रयोजन रहता है, और न कर्म न करनेसे ही कोई प्रयोजन रहता है, तथा सम्पूर्ण प्राणियोंमें (किसी भी प्राणीके साथ) इसका किञ्चिन्मात्र भी स्वार्थका सम्बन्ध नहीं रहता। `,
  },
  '3:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '3:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '3:23': {
    explanation: `।।3.23 -- 3.24।।  हे पार्थ! अगर मैं किसी समय सावधान होकर कर्तव्यकर्म न करूँ तो बड़ी हानि हो जाय; क्योंकि मनुष्य सब प्रकारसे मेरे ही मार्गका अनुसरण करते हैं। यदि मैं कर्म न करूँ, तो ये सब मनुष्य नष्ट-भ्रष्ट हो जायँ और मैं वर्णसंकरताको करनेवाला होऊँ तथा इस समस्त प्रजाको नष्ट करनेवाला बनूँ।`,
  },
  '3:24': {
    explanation: `।।3.23 -- 3.24।।  हे पार्थ ! अगर मैं किसी समय सावधान होकर कर्तव्य-कर्म न करूँ (तो बड़ी हानि हो जाय; क्योंकि) मनुष्य सब प्रकारसे मेरे ही मार्गका अनुसरण करते हैं। यदि मैं कर्म न करूँ, तो ये सब मनुष्य नष्ट-भ्रष्ट हो जायँ और मैं वर्णसंकरताको करनेवाला  तथा इस समस्त प्रजाको नष्ट करनेवाला बनूँ।
 `,
  },
  '3:25': {
    explanation: `।।3.25 -- 3.26।। हे भरतवंशोद्भव अर्जुन! कर्ममें आसक्त हुए अज्ञानीजन जिस प्रकार कर्म करते हैं, आसक्तिरहित विद्वान भी लोकसंग्रह करना चाहता हुआ उसी प्रकार कर्म करे।  तत्त्वज्ञ महापुरुष कर्मोंमें आसक्तिवाले अज्ञानी मनुष्योंकी बुद्धिमें भ्रम उत्पन्न न करे, प्रत्युत स्वयं समस्त कर्मोंको अच्छी तरहसे करता हुआ उनसे भी वैसे ही करवाये।`,
  },
  '3:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '3:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '3:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '3:29': {
    explanation: `।।3.29।। प्रकृतिजन्य गुणोंसे अत्यन्त मोहित हुए अज्ञानी मनुष्य गुणों और कर्मोंमें आसक्त रहते हैं। उन पूर्णतया न समझनेवाले मन्दबुद्धि अज्ञानियोंको पूर्णतया जाननेवाला ज्ञानी मनुष्य विचलित न करे। `,
  },
  '3:31': {
    explanation: `हे केशव! मैं अपशकुन ही देख रहा हूँ। युद्ध में स्वजनों को मारने में मुझे कोई कल्याण नहीं दिखता।`,
  },
  '3:32': {
    explanation: `आकाश में एक साथ हज़ार सूर्य उदय हों तो जो प्रकाश हो, वह उस महात्मा (विश्वरूप) के तेज के समान होगा।`,
  },
  '3:33': {
    explanation: `।।3.33।। सम्पूर्ण प्राणी प्रकृतिको प्राप्त होते हैं। ज्ञानी महापुरुष भी अपनी प्रकृतिके अनुसार चेष्टा करता है। फिर इसमें किसीका हठ क्या करेगा?`,
  },
  '3:34': {
    explanation: `हे पार्थ! जो तुमने देखा वह मेरी योगमाया से प्रकट किया गया था। अब मैं तुम्हें अपना शाश्वत रूप बताता हूँ।`,
  },
  '3:36': {
    explanation: `।।3.36।। अर्जुन बोले - हे वार्ष्णेय ! फिर यह मनुष्य न चाहता हुआ भी जबर्दस्ती लगाये हुएकी तरह किससे प्रेरित होकर पापका आचरण करता है?`,
  },
  '3:37': {
    explanation: `।।3.37।। श्रीभगवान् बोले - रजोगुणसे उत्पन्न हुआ  यह काम ही क्रोध  है। यह बहुत खानेवाला और महापापी है। इस विषयमें तू इसको ही वैरी जान। `,
  },
  '3:38': {
    explanation: `सुख-दुःख, लाभ-हानि और जय-पराजय को समान करके तब युद्ध के लिए तैयार हो। इस प्रकार तुम पाप नहीं प्राप्त करोगे।`,
  },
  '3:39': {
    explanation: `।।3.39।। और हे कुन्तीनन्दन ! इस अग्निके समान कभी तृप्त न होनेवाले और विवेकियोंके नित्य वैरी इस कामके द्वारा मनुष्यका विवेक ढका हुआ है। `,
  },
  '3:40': {
    explanation: `।।3.40।। इन्द्रियाँ, मन और बुद्धि इस कामके वास-स्थान कहे गये हैं। यह काम इन- (इन्द्रियाँ, मन और बुद्धि-) के द्वारा ज्ञानको ढककर देहाभिमानी मनुष्यको मोहित करता है। `,
  },
  '3:41': {
    explanation: `।।3.41।। इसलिये हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! तू सबसे पहले इन्द्रियोंको वशमें करके इस ज्ञान और विज्ञानका नाश करनेवाले महान् पापी कामको अवश्य ही बलपूर्वक मार डाल। `,
  },
  '3:43': {
    explanation: `।।3.42 -- 3.43।। इन्द्रियोंको (स्थूलशरीरसे) पर (श्रेष्ठ, सबल, प्रकाशक, व्यापक तथा सूक्ष्म) कहते हैं। इन्द्रियोंसे पर मन है, मनसे भी पर बुद्धि है औऱ जो बुद्धिसे भी पर है वह (काम) है। इस तरह बुद्धिसे पर - (काम-) को जानकर अपने द्वारा अपने-आपको वशमें करके हे महाबाहो ! तू इस कामरूप दुर्जय शत्रुको मार डाल।
 `,
  },
  '4:1': {
    explanation: `हे भारत! जब-जब धर्म की हानि और अधर्म की वृद्धि होती है, तब-तब मैं अपने आपको प्रकट करता हूँ।`,
  },
  '4:2': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '4:3': {
    explanation: `हे भारत! प्रत्येक व्यक्ति की श्रद्धा उसके स्वभाव (सत्त्व) के अनुसार होती है। यह पुरुष श्रद्धामय है — जैसी श्रद्धा, वैसा पुरुष।`,
  },
  '4:4': {
    explanation: `।।4.4।। अर्जुन बोले - आपका जन्म तो अभीका है और सूर्यका जन्म बहुत पुराना है; अतः आपने ही सृष्टिके आदिमें सूर्यसे यह योग कहा था - यह बात मैं कैसे समझूँ?`,
  },
  '4:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '4:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '4:9': {
    explanation: `।।4.9।। हे अर्जुन ! मेरे जन्म और कर्म दिव्य हैं। इस प्रकार (मेरे जन्म और कर्मको) जो मनुष्य तत्त्वसे जान लेता अर्थात् दृढ़तापूर्वक मान लेता है, वह शरीरका त्याग करके पुनर्जन्मको प्राप्त नहीं होता, प्रत्युत मुझे प्राप्त होता है। `,
  },
  '4:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '4:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '4:12': {
    explanation: `।।4.12।। कर्मोंकी सिद्धि (फल) चाहनेवाले मनुष्य देवताओंकी उपासना किया करते हैं; क्योंकि इस मनुष्यलोकमें कर्मोंसे उत्पन्न होनेवाली सिद्धि जल्दी मिल जाती है। `,
  },
  '4:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '4:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '4:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '4:16': {
    explanation: `।।4.16।। कर्म क्या है और अकर्म क्या है -- इस प्रकार इस विषयमें विद्वान् भी मोहित हो जाते हैं। अतः वह कर्म-तत्त्व मैं तुम्हें भलीभाँति कहूँगा, जिसको जानकर तू अशुभ- (संसार-बन्धन-) से मुक्त हो जायगा। `,
  },
  '4:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '4:18': {
    explanation: `।।4.18।। जो मनुष्य कर्ममें अकर्म देखता है और जो अकर्ममें कर्म देखता है, वह मनुष्योंमें बुद्धिमान् है,  योगी है और सम्पूर्ण कर्मोंको करनेवाला  है। `,
  },
  '4:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '4:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '4:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '4:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '4:23': {
    explanation: `।।4.23।। जिसकी आसक्ति सर्वथा मिट गयी है, जो मुक्त हो गया है, जिसकी बुद्धि स्वरूपके ज्ञानमें स्थित है, ऐसे केवल यज्ञके लिये कर्म करनेवाले मनुष्यके सम्पूर्ण कर्म विलीन हो जाते हैं। `,
  },
  '4:24': {
    explanation: `।।4.24।। जिस यज्ञमें अर्पण भी ब्रह्म है, हवी भी ब्रह्म है और ब्रह्मरूप कर्ताके द्वारा ब्रह्मरूप अग्निमें आहुति देनारूप क्रिया भी ब्रह्म है, (ऐसे यज्ञको करनेवाले) जिस मनुष्यकी ब्रह्ममें ही कर्म-समाधि हो गयी है, उसके द्वारा प्राप्त करनेयोग्य फल भी ब्रह्म ही है। `,
  },
  '4:25': {
    explanation: `।।4.25।। अन्य योगीलोग भगवदर्पणरूप यज्ञका ही अनुष्ठान करते हैं और दूसरे योगीलोग ब्रह्मरूप अग्निमें विचाररूप यज्ञके द्वारा ही जीवात्मारूप यज्ञका हवन करते हैं। `,
  },
  '4:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '4:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '4:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '4:29': {
    explanation: `।।4.29 -- 4.30।। दूसरे कितने ही प्राणायामके परायण हुए योगीलोग अपानमें प्राणका पूरक करके, प्राण और अपानकी गति रोककर फिर प्राणमें अपानका हवन करते हैं; तथा अन्य कितने ही नियमित आहार करनेवाले प्राणोंका प्राणोंमें हवन किया करते हैं। ये सभी साधक यज्ञोंद्वारा पापोंका नाश करनेवाले और यज्ञोंको जाननेवाले हैं।`,
  },
  '4:31': {
    explanation: `हे केशव! मैं अपशकुन ही देख रहा हूँ। युद्ध में स्वजनों को मारने में मुझे कोई कल्याण नहीं दिखता।`,
  },
  '4:32': {
    explanation: `आकाश में एक साथ हज़ार सूर्य उदय हों तो जो प्रकाश हो, वह उस महात्मा (विश्वरूप) के तेज के समान होगा।`,
  },
  '4:33': {
    explanation: `।।4.33।। हे परन्तप अर्जुन ! द्रव्यमय यज्ञसे ज्ञानयज्ञ श्रेष्ठ है। सम्पूर्ण कर्म और पदार्थ ज्ञान-(तत्त्वज्ञान-) में समाप्त हो जाते हैं। `,
  },
  '4:34': {
    explanation: `हे पार्थ! जो तुमने देखा वह मेरी योगमाया से प्रकट किया गया था। अब मैं तुम्हें अपना शाश्वत रूप बताता हूँ।`,
  },
  '4:35': {
    explanation: `अपने स्वधर्म में मरना भला है, चाहे वह अपूर्ण हो; परधर्म को अच्छी तरह से करना भयावह है।`,
  },
  '4:36': {
    explanation: `।।4.36।। अगर तू सब पापियोंसे भी अधिक पापी है, तो भी तू ज्ञानरूपी नौकाके द्वारा निःसन्देह सम्पूर्ण पापसमुद्रसे अच्छी तरह तर जायगा। `,
  },
  '4:37': {
    explanation: `।।4.37।। हे अर्जुन ! जैसे प्रज्वलित अग्नि ईंधनोंको सर्वथा भस्म कर देती है, ऐसे ही ज्ञानरूपी अग्नि सम्पूर्ण कर्मोंको सर्वथा भस्म कर देती है। `,
  },
  '4:38': {
    explanation: `सुख-दुःख, लाभ-हानि और जय-पराजय को समान करके तब युद्ध के लिए तैयार हो। इस प्रकार तुम पाप नहीं प्राप्त करोगे।`,
  },
  '4:39': {
    explanation: `।।4.39।। जो जितेन्द्रिय तथा साधन-परायण है, ऐसा श्रद्धावान् मनुष्य ज्ञानको प्राप्त होता है और ज्ञानको प्राप्त होकर वह तत्काल परम शान्तिको प्राप्त हो जाता है। `,
  },
  '4:40': {
    explanation: `।।4.40।। विवेकहीन और श्रद्धारहित संशयात्मा मनुष्यका पतन हो जाता है। ऐसे संशयात्मा मनुष्यके लिये न यह लोक  है न परलोक है और न सुख ही है। `,
  },
  '4:41': {
    explanation: `।।4.41।। हे धनञ्जय ! योग- (समता-) के द्वारा जिसका सम्पूर्ण कर्मोंसे सम्बन्ध-विच्छेद हो गया है और ज्ञानके द्वारा जिसके सम्पूर्ण संशयोंका नाश हो गया है, ऐसे स्वरूप-परायण मनुष्यको कर्म नहीं बाँधते। `,
  },
  '4:42': {
    explanation: `जो-जो आचरण श्रेष्ठ पुरुष करता है, अन्य लोग भी वही करते हैं। वह जो प्रमाण स्थापित करता है, संसार उसी का अनुसरण करता है।`,
  },
  '5:1': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '5:2': {
    explanation: `और हे भारत! सभी क्षेत्रों में क्षेत्रज्ञ (क्षेत्र को जानने वाला) भी मुझे ही जानो। क्षेत्र और क्षेत्रज्ञ का यह ज्ञान ही मेरे मत में सच्चा ज्ञान है।`,
  },
  '5:3': {
    explanation: `हे भारत! प्रत्येक व्यक्ति की श्रद्धा उसके स्वभाव (सत्त्व) के अनुसार होती है। यह पुरुष श्रद्धामय है — जैसी श्रद्धा, वैसा पुरुष।`,
  },
  '5:4': {
    explanation: `।।5.4।। बेसमझ लोग सांख्ययोग और कर्मयोगको अलग-अलग फलवाले कहते हैं, न कि पण्डितजन; क्योंकि इन दोनोंमेंसे एक साधनमें भी अच्छी तरहसे स्थित मनुष्य दोनोंके फलरूप परमात्माको प्राप्त कर लेता है। `,
  },
  '5:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '5:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '5:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '5:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '5:9': {
    explanation: `।।5.8 -- 5.9।। तत्त्वको जाननेवाला सांख्ययोगी देखता, सुनता, छूता, सूँघता, खाता, चलता, ग्रहण करता, बोलता, मल-मूत्र का त्याग करता, सोता हुआ, श्वास लेता तथा आँखें खोलता और मूँदता हुआ भी 'सम्पूर्ण इन्द्रियाँ इन्द्रियोंके विषयोंमें बरत रही हैं' -- ऐसा समझकर 'मैं (स्वयं) कुछ भी नहीं करता हूँ' -- ऐसा माने।
 `,
  },
  '5:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '5:12': {
    explanation: `।।5.12।। कर्मयोगी कर्मफलका त्याग करके नैष्ठिकी शान्तिको प्राप्त होता है। परन्तु सकाम मनुष्य कामनाके कारण फलमें आसक्त होकर बँध जाता है। `,
  },
  '5:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '5:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '5:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '5:16': {
    explanation: `।।5.16।। परन्तु जिन्होंने अपने जिस ज्ञान-(विवक-) के द्वारा उस अज्ञानका नाश कर दिया है, उनका वह ज्ञान सूर्यकी तरह परमतत्त्व परमात्माको प्रकाशित कर देता है। `,
  },
  '5:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '5:18': {
    explanation: `।।5.18।। ज्ञानी महापुरुष विद्या-विनययुक्त ब्राह्मणमें और चाण्डालमें तथा गाय, हाथी एवं कुत्तेमें भी समरूप परमात्माको देखनेवाले होते हैं। `,
  },
  '5:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '5:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '5:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '5:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '5:23': {
    explanation: `।।5.23।। इस मनुष्य-शरीरमें जो कोई (मनुष्य) शरीर छूटनेसे पहले ही काम-क्रोधसे उत्पन्न होनेवाले वेगको सहन करनेमें समर्थ होता है, वह नर योगी है और वही सुखी है। `,
  },
  '5:24': {
    explanation: `।।5.24।। जो मनुष्य केवल परमात्मामें सुखवाला है और केवल परमात्मामें रमण करनेवाला है तथा जो केवल परमात्मामें ज्ञानवाला है, वह ब्रह्ममें अपनी स्थितिका अनुभव करनेवाला सांख्ययोगी निर्वाण ब्रह्मको प्राप्त होता है। `,
  },
  '5:25': {
    explanation: `।।5.25।। जिनका शरीर मन-बुद्धि-इन्द्रियोंसहित वशमें है, जो सम्पूर्ण प्राणियोंके हितमें रत हैं, जिनके सम्पूर्ण संशय मिट गये हैं, जिनके सम्पूर्ण कल्मष (दोष) नष्ट हो गये हैं, वे विवेकी साधक निर्वाण ब्रह्मको प्राप्त होते हैं। `,
  },
  '5:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '5:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '5:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '5:29': {
    explanation: `।।5.29।। भक्त मुझे सब यज्ञों और तपोंका भोक्ता, सम्पूर्ण लोकोंका महान् ईश्वर तथा सम्पूर्ण प्राणियोंका सुहृद् (स्वार्थरहित दयालु और प्रेमी) जानकर शान्तिको प्राप्त हो जाता है।`,
  },
  '6:1': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '6:2': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '6:3': {
    explanation: `हे भारत! प्रत्येक व्यक्ति की श्रद्धा उसके स्वभाव (सत्त्व) के अनुसार होती है। यह पुरुष श्रद्धामय है — जैसी श्रद्धा, वैसा पुरुष।`,
  },
  '6:4': {
    explanation: `।।6.4।। जिस समय न इन्द्रियोंके भोगोंमें तथा न कर्मोंमें ही आसक्त होता है, उस समय वह सम्पूर्ण संकल्पोंका त्यागी मनुष्य योगारूढ़ कहा जाता है। `,
  },
  '6:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '6:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '6:9': {
    explanation: `।।6.9।। सुहृद्, मित्र, वैरी, उदासीन, मध्यस्थ, द्वेष्य और सम्बन्धियोंमें तथा साधु-आचरण करनेवालोंमें और पाप-आचरण करनेवालोंमें भी समबुद्धिवाला मनुष्य श्रेष्ठ है। `,
  },
  '6:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '6:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '6:12': {
    explanation: `।।6.12।। उस आसनपर बैठकर चित्त और इन्द्रियोंकी क्रियाओंको वशमें रखते हुए मनको एकाग्र करके अन्तःकरणकी शुद्धिके लिये योगका अभ्यास करे। `,
  },
  '6:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '6:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '6:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '6:16': {
    explanation: `।।6.16।। हे अर्जुन ! यह योग न तो अधिक खानेवालेका और न बिलकुल न खानेवालेका तथा न अधिक सोनेवालेका और न बिलकुल न सोनेवालेका ही सिद्ध होता है। `,
  },
  '6:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '6:18': {
    explanation: `।।6.18।। वशमें किया हुआ चित्त जिस कालमें अपने स्वरूपमें ही स्थित हो जाता है और स्वयं सम्पूर्ण पदार्थोंसे निःस्पृह हो जाता है, उस कालमें वह योगी है - ऐसा कहा जाता है। `,
  },
  '6:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '6:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '6:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '6:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '6:23': {
    explanation: `।।6.23।। जिसमें दुःखोंके संयोगका ही वियोग है, उसीको 'योग' नामसे जानना चाहिये। (वह योग जिस ध्यानयोगका लक्ष्य है,) उस ध्यानयोगका अभ्यास न उकताये हुए चित्तसे निश्चयपूर्वक करना चाहिये।`,
  },
  '6:24': {
    explanation: `।।6.24।। संकल्पसे उत्पन्न होनेवाली सम्पूर्ण कामनाओंका सर्वथा त्याग करके और मनसे ही इन्द्रिय-समूहको सभी ओरसे हटाकर। `,
  },
  '6:25': {
    explanation: `।।6.25।। धैर्ययुक्त बुद्धिके द्वारा संसारसे धीरे-धीरे उपराम हो जाय और परमात्मस्वरूपमें मन-(बुद्धि-) को सम्यक् प्रकारसे स्थापन करके फिर कुछ भी चिन्तन न करे। `,
  },
  '6:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '6:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '6:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '6:29': {
    explanation: `।।6.29।। सब जगह अपने स्वरूपको देखनेवाला और ध्यानयोगसे युक्त अन्तःकरणवाला योगा अपने स्वरूपको सम्पूर्ण प्राणियोंमें स्थित देखता है और सम्पूर्ण प्राणियोंको अपने स्वरूपमें देखता है। `,
  },
  '6:31': {
    explanation: `हे केशव! मैं अपशकुन ही देख रहा हूँ। युद्ध में स्वजनों को मारने में मुझे कोई कल्याण नहीं दिखता।`,
  },
  '6:32': {
    explanation: `आकाश में एक साथ हज़ार सूर्य उदय हों तो जो प्रकाश हो, वह उस महात्मा (विश्वरूप) के तेज के समान होगा।`,
  },
  '6:33': {
    explanation: `।।6.33।। अर्जुन बोले -- हे मधुसूदन ! आपने समतापूर्वक जो यह योग कहा है, मनकी चञ्चलताके कारण मैं इस योगकी स्थिर स्थिति नहीं देखता हूँ। `,
  },
  '6:34': {
    explanation: `हे पार्थ! जो तुमने देखा वह मेरी योगमाया से प्रकट किया गया था। अब मैं तुम्हें अपना शाश्वत रूप बताता हूँ।`,
  },
  '6:35': {
    explanation: `अपने स्वधर्म में मरना भला है, चाहे वह अपूर्ण हो; परधर्म को अच्छी तरह से करना भयावह है।`,
  },
  '6:36': {
    explanation: `।।6.36।। जिसका मन पूरा वशमें नहीं है, उसके द्वारा योग प्राप्त होना कठिन है। परन्तु उपायपूर्वक यत्न करनेवाले वश्यात्माको योग प्राप्त हो सकता है, ऐसा मेरा मत है। `,
  },
  '6:37': {
    explanation: `।।6.37।। अर्जुन बोले - हे कृष्ण ! जिसकी साधनमें श्रद्धा है, पर जिसका प्रयत्न शिथिल है, वह अन्तसमयमें अगर योगसे विचलितमना हो जाय, तो वह योगसिद्धिको प्राप्त न करके किस गतिको चला जाता है?`,
  },
  '6:38': {
    explanation: `सुख-दुःख, लाभ-हानि और जय-पराजय को समान करके तब युद्ध के लिए तैयार हो। इस प्रकार तुम पाप नहीं प्राप्त करोगे।`,
  },
  '6:39': {
    explanation: `।।6.39।। हे कृष्ण! मेरे इस सन्देहका सर्वथा छेदन करनेके लिये आप ही योग्य हैं; क्योंकि इस संशयका छेदन करनेवाला आपके सिवाय दूसरा कोई हो नहीं सकता। `,
  },
  '6:40': {
    explanation: `।।6.40।। श्रीभगवान् बोले -- हे पृथानन्दन ! उसका न तो इस लोकमें और न परलोकमें ही विनाश होता है; क्योंकि हे प्यारे ! कल्याणकारी काम करनेवाला कोई भी मनुष्य दुर्गतिको प्राप्त नहीं जाता। `,
  },
  '6:41': {
    explanation: `।।6.41।। वह योगभ्रष्ट पुण्यकर्म करनेवालोंके लोकोंको प्राप्त होकर और वहाँ बहुत वर्षोंतक रहकर फिर यहाँ शुद्ध  श्रीमानोंके घरमें जन्म लेता है। `,
  },
  '6:42': {
    explanation: `जो-जो आचरण श्रेष्ठ पुरुष करता है, अन्य लोग भी वही करते हैं। वह जो प्रमाण स्थापित करता है, संसार उसी का अनुसरण करता है।`,
  },
  '6:43': {
    explanation: `।।6.43।। हे कुरुनन्दन ! वहाँपर उसको पूर्वजन्मकृत साधन-सम्पत्ति अनायास ही प्राप्त हो जाती है। फिर उससे वह साधनकी सिद्धिके विषयमें पुनः विशेषतासे यत्न करता है। `,
  },
  '6:44': {
    explanation: `।।6.44।। वह (श्रीमानोंके घरमें जन्म लेनेवाला योगभ्रष्ट मनुष्य) भोगोंके परवश होता हुआ भी पूर्वजन्ममें किये हुए अभ्यास-(साधन-) के कारण ही परमात्माकी तरफ खिंच जाता है; क्योंकि योग-(समता-) का जिज्ञासु भी वेदोंमें कहे हुए सकाम कर्मोंका अतिक्रमण कर जाता है। `,
  },
  '6:45': {
    explanation: `।।6.45।। परन्तु जो योगी प्रयत्नपूर्वक यत्न करता है और जिसके पाप नष्ट हो गये हैं तथा जो अनेक जन्मोंसे सिद्ध हुआ है, वह योगी फिर परमगतिको प्राप्त हो जाता है। `,
  },
  '6:46': {
    explanation: `यदि धार्तराष्ट्र शस्त्र-पाणि होकर युद्ध में मुझ अप्रतिकार करने वाले को मार दें, तो यह मेरे लिए अधिक कल्याणकारक होगा।`,
  },
  '6:47': {
    explanation: `संजय बोले — इस प्रकार कहकर, शोक से व्याकुल मन वाले अर्जुन ने रणभूमि में अपने बाण और धनुष छोड़कर रथ के पिछले भाग में बैठ गए।`,
  },
  '7:1': {
    explanation: `हे धनंजय! मुझसे श्रेष्ठ कोई और नहीं है। यह सारा जगत मुझ पर उसी प्रकार पिरोया हुआ है जैसे मोतियों की माला में धागे पर मोती।`,
  },
  '7:2': {
    explanation: `हे कुन्तीपुत्र! मैं जल में रस, चन्द्रमा और सूर्य में प्रभा, सभी वेदों में ओंकार, आकाश में शब्द, और मनुष्यों में पुरुषत्व (पौरुष) हूँ।`,
  },
  '7:3': {
    explanation: `हे भारत! प्रत्येक व्यक्ति की श्रद्धा उसके स्वभाव (सत्त्व) के अनुसार होती है। यह पुरुष श्रद्धामय है — जैसी श्रद्धा, वैसा पुरुष।`,
  },
  '7:4': {
    explanation: `।।7.4 -- 7.5।।  पृथ्वी, जल, तेज, वायु, आकाश -- ये पञ्चमहाभूत और मन, बुद्धि तथा अहंकार -- यह आठ प्रकारके भेदोंवाली मेरी 'अपरा' प्रकृति है। हे महाबाहो ! इस अपरा प्रकृतिसे भिन्न जीवरूप बनी हुई मेरी 'परा' प्रकृतिको जान, जिसके द्वारा यह जगत् धारण किया जाता है।`,
  },
  '7:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '7:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '7:9': {
    explanation: `।।7.9।। पृथ्वीमें पवित्र गन्ध मैं हूँ, और अग्निमें तेज मैं हूँ, तथा सम्पूर्ण प्राणियोंमें जीवनीशक्ति मैं हूँ और तपस्वियोंमें तपस्या मैं हूँ। `,
  },
  '7:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '7:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '7:12': {
    explanation: `।।7.12।। (और तो क्या कहूँ)  जितने भी सात्त्विक, राजस और तामस भाव हैं, वे सब मुझ से ही होते हैं -- ऐसा समझो। पर मैं उनमें और वे मेरेमें नहीं हैं। `,
  },
  '7:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '7:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '7:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '7:16': {
    explanation: `।।7.16।। हे भरतवंशियोंमें श्रेष्ठ अर्जुनव ! पवित्र कर्म करनेवाले अर्थार्थी, आर्त, जिज्ञासु और ज्ञानी अर्थात् प्रेमी -- ये चार प्रकारके मनुष्य मेरा भजन करते हैं अर्थात् मेरे शरण होते हैं। `,
  },
  '7:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '7:18': {
    explanation: `।।7.18।। पहले कहे हुए सब-के-सब भक्त बड़े उदार (श्रेष्ठ भाववाले) हैं। परन्तु ज्ञानी (प्रेमी) तो मेरा स्वरूप ही है -- ऐसा मेरा मत है। कारण कि वह युक्तात्मा है और जिससे श्रेष्ठ दूसरी कोई गति नहीं है, ऐसे मेरेमें ही दृढ़ आस्थावाला है। `,
  },
  '7:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '7:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '7:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '7:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '7:23': {
    explanation: `।।7.23।। परन्तु उन अल्पबुद्धिवाले मनुष्योंको उन देवताओंकी आराधनाका फल अन्तवाला (नाशवान्) ही मिलता है। देवताओंका पूजन करनेवाले देवताओंको प्राप्त होते हैं और मेरे भक्त मेरे ही प्राप्त होते हैं। `,
  },
  '7:24': {
    explanation: `।।7.24।। बुद्धिहीन मनुष्य मेरे सर्वश्रेष्ठ अविनाशी परमभावको न जानते हुए अव्यक्त (मन-इन्द्रियोंसे पर) मुझ सच्चिदानन्दघन परमात्माको मनुष्यकी तरह ही शरीर धारण करनेवाला मानते हैं। `,
  },
  '7:25': {
    explanation: `।।7.25।। जो मूढ़ मनुष्य मेरेको अज और अविनाशी ठीक तरहसे नहीं जानते (मानते), उन सबके सामने योगमायासे अच्छी तरहसे आवृत हुआ मैं प्रकट नहीं होता। `,
  },
  '7:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '7:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '7:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '7:29': {
    explanation: `।।7.29।।  जरा (वृद्धावस्था) और मरण (मृत्यु) से मोक्ष पानेके लिये जो  मेरा आश्रय लेकर प्रयत्न करते हैं, वे उस ब्रह्मको, सम्पूर्ण अध्यात्मको और सम्पूर्ण कर्मको भी जान जाते हैं। `,
  },
  '7:30': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '8:1': {
    explanation: `जो अंत समय में मुझे ही स्मरण करते हुए शरीर त्यागता है, वह मेरे स्वरूप को प्राप्त होता है। इसमें कोई संशय नहीं।`,
  },
  '8:2': {
    explanation: `इसलिए सब समय मुझे स्मरण करते हुए युद्ध भी करो। मुझमें मन और बुद्धि अर्पित करने से तुम निःसंदेह मुझे ही प्राप्त होगे।`,
  },
  '8:3': {
    explanation: `हे भारत! प्रत्येक व्यक्ति की श्रद्धा उसके स्वभाव (सत्त्व) के अनुसार होती है। यह पुरुष श्रद्धामय है — जैसी श्रद्धा, वैसा पुरुष।`,
  },
  '8:4': {
    explanation: `।।8.4।। हे देहधारियोंमें श्रेष्ठ अर्जुन ! क्षरभाव अर्थात् नाशवान् पदार्थको अधिभूत कहते हैं, पुरुष अर्थात् हिरण्यगर्भ ब्रह्माजी अधिदैव हैं और इस देहमें अन्तर्यामीरूपसे मैं ही अधियज्ञ हूँ। `,
  },
  '8:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '8:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '8:9': {
    explanation: `।।8.9।। जो सर्वज्ञ, पुराण, शासन करनेवाला, सूक्ष्म-से-सूक्ष्म, सबका धारण-पोषण करनेवाला, अज्ञानसे अत्यन्त परे, सूर्यकी तरह प्रकाशस्वरूप -- ऐसे अचिन्त्य स्वरूपका चिन्तन करता है। `,
  },
  '8:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '8:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '8:12': {
    explanation: `।।8.12 -- 8.13।। (इन्द्रियोंके) सम्पूर्ण द्वारोंको रोककर मनका हृदयमें निरोध करके और अपने प्राणोंको मस्तकमें स्थापित करके योगधारणामें सम्यक् प्रकारसे स्थित हुआ जो 'ऊँ' इस एक अक्षर ब्रह्मका  उच्चारण और मेरा स्मरण करता हुआ शरीरको छोड़कर जाता है, वह परमगतिको प्राप्त होता है।`,
  },
  '8:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '8:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '8:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '8:16': {
    explanation: `।।8.16।। हे अर्जुन ! ब्रह्मलोकतक सभी लोक पुनरावर्ती है; परन्तु हे कौन्तेय ! मुझे प्राप्त होनेपर पुनर्जन्म नहीं होता। `,
  },
  '8:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '8:18': {
    explanation: `।।8.18।। ब्रह्माजीके दिनके आरम्भकालमें अव्यक्त- (ब्रह्माजीके सूक्ष्म-शरीर-) से सम्पूर्ण प्राणी पैदा होते हैं और ब्रह्माजीकी रातके आरम्भकालमें उसी अव्यक्तमें सम्पूर्ण प्राणी लीन हो जाते हैं। `,
  },
  '8:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '8:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '8:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '8:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '8:23': {
    explanation: `।।8.23।। हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! जिस काल अर्थात् मार्गमें शरीर छोड़कर गये हुए योगी अनावृत्तिको प्राप्त होते हैं अर्थात् पीछे लौटकर नहीं आते और (जिस मार्गमें गये हुए) आवृत्तिको प्राप्त होते हैं अर्थात् पीछे लौटकर आते हैं, उस कालको अर्थात् दोनों मार्गोंको मैं कहूँगा। `,
  },
  '8:24': {
    explanation: `।।8.24।। जिस मार्गमें प्रकाशस्वरूप अग्निका अधिपति देवता, दिनका अधिपति देवता, शुक्लपक्षका अधिपति देवता, और छः महीनोंवाले उत्तरायणका अधिपति देवता है, शरीर छोड़कर उस मार्गसे गये हुए ब्रह्मवेत्ता पुरुष (पहले ब्रह्मलोकको प्राप्त होकर पीछे ब्रह्माजीके साथ) ब्रह्मको प्राप्त हो जाते हैं। `,
  },
  '8:25': {
    explanation: `।।8.25।। जिस मार्गमें धूमका अधिपति देवता, रात्रिका अधिपति देवता, कृष्णपक्षका अधिपति देवता और छः महीनोंवाले दक्षिणायनका अधिपति देवता है, शरीर छोड़कर उस मार्गसे गया हुआ योगी (सकाम मनुष्य) चन्द्रमाकी ज्योतिको प्राप्त होकर लौट आता है अर्थात् जन्म-मरणको प्राप्त होता है। `,
  },
  '8:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '8:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '8:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '9:1': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '9:2': {
    explanation: `जो अक्षर, अनिर्देश्य, अव्यक्त, सर्वव्यापी, अचिंत्य, अचल और ध्रुव की उपासना करते हैं...`,
  },
  '9:3': {
    explanation: `हे भारत! प्रत्येक व्यक्ति की श्रद्धा उसके स्वभाव (सत्त्व) के अनुसार होती है। यह पुरुष श्रद्धामय है — जैसी श्रद्धा, वैसा पुरुष।`,
  },
  '9:4': {
    explanation: `।।9.4 -- 9.5।। यह सब संसार मेरे निराकार स्वरूपसे व्याप्त है। सम्पूर्ण प्राणी मेरेमें स्थित हैं; परन्तु मैं उनमें स्थित नहीं हूँ तथा वे प्राणी भी मुझ में स्थित नहीं हैं -- मेरे इस ईश्वर-सम्बन्धी योग-(सामर्थ्य-) को देख ! सम्पूर्ण प्राणियोंको उत्पन्न करनेवाला और उनका धारण, भरण-पोषण करनेवाला मेरा स्वरूप उन प्राणियोंमें स्थित नहीं है।`,
  },
  '9:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '9:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '9:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '9:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '9:9': {
    explanation: `।।9.9।। हे धनञ्जय ! उन (सृष्टि-रचना आदि) कर्मोंमें अनासक्त और उदासीनकी तरह रहते हुए मेरेको वे कर्म नहीं बाँधते।`,
  },
  '9:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '9:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '9:12': {
    explanation: `।।9.12।। जिनकी सब आशाएँ व्यर्थ होती हैं, सब शुभ-कर्म व्यर्थ होते हैं और सब ज्ञान व्यर्थ होते हैं अर्थात् जिनकी आशाएँ, कर्म और ज्ञान सत्-फल देनेवाले नहीं होते, ऐसे अविवेकी मनुष्य आसुरी, राक्षसी और मोहिनी फकृतिका आश्रय लेते हैं।`,
  },
  '9:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '9:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '9:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '9:16': {
    explanation: `।।9.16 -- 9.18।।  क्रतु मैं हूँ, यज्ञ मैं हूँ, स्वधा मैं हूँ, औषध मैं हूँ, मन्त्र मैं हूँ, घृत मैं हूँ, अग्नि मैं हूँ और हवनरूप क्रिया भी मैं हूँ। जाननेयोग्य पवित्र, ओंकार, ऋग्वेद, सामवेद और यजुर्वेद भी मैं ही हूँ। इस सम्पूर्ण जगत्का पिता, धाता, माता, पितामह, गति, भर्ता, प्रभु, साक्षी, निवास, आश्रय, सुहृद्, उत्पत्ति, प्रलय, स्थान, निधान तथा अविनाशी बीज भी मैं ही हूँ।`,
  },
  '9:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '9:18': {
    explanation: `।।9.16 -- 9.18।।  क्रतु मैं हूँ, यज्ञ मैं हूँ, स्वधा मैं हूँ, औषध मैं हूँ, मन्त्र मैं हूँ, घृत मैं हूँ, अग्नि मैं हूँ और हवनरूप क्रिया भी मैं हूँ। जाननेयोग्य पवित्र, ओंकार, ऋग्वेद, सामवेद और यजुर्वेद भी मैं ही हूँ। इस सम्पूर्ण जगत्का पिता, धाता, माता, पितामह, गति, भर्ता, प्रभु, साक्षी, निवास, आश्रय, सुहृद्, उत्पत्ति, प्रलय, स्थान, निधान तथा अविनाशी बीज भी मैं ही हूँ।`,
  },
  '9:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '9:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '9:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '9:23': {
    explanation: `।।9.23।। हे कुन्तीनन्दन! जो भी भक्त (मनुष्य) श्रद्धापूर्वक अन्य देवताओंका पूजन करते हैं, वे भी करते हैं मेरा ही पूजन, पर करते है अविधिपूर्वक  `,
  },
  '9:24': {
    explanation: `।।9.24।। क्योंकि मैं ही सम्पूर्ण यज्ञोंका भोक्ता और स्वामी भी हूँ;  परन्तु वे मेरेको तत्त्वसे नहीं जानते, इसीसे उनका पतन होता है।`,
  },
  '9:25': {
    explanation: `।।9.25।। (सकामभावसे) देवताओंका पूजन करनेवाले (शरीर छोड़नेपर) देवताओंको प्राप्त होते हैं। पितरोंका पूजन करनेवाले पितरोंको प्राप्त होते हैं। भूत-प्रेतोंका पूजन करनेवाले भूत-प्रेतोंको प्राप्त होते हैं। परन्तु मेरा पूजन करनेवाले मुझे ही प्राप्त होते हैं।`,
  },
  '9:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '9:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '9:29': {
    explanation: `।।9.29।। मैं सम्पूर्ण प्राणियोंमें समान हूँ। उन प्राणियोंमें न तो कोई मेरा द्वेषी है और न कोई प्रिय है। परन्तु जो भक्तिपूर्वक मेरा भजन करते हैं, वे मेरेमें हैं और मैं  उनमें हूँ।`,
  },
  '9:31': {
    explanation: `हे केशव! मैं अपशकुन ही देख रहा हूँ। युद्ध में स्वजनों को मारने में मुझे कोई कल्याण नहीं दिखता।`,
  },
  '9:32': {
    explanation: `आकाश में एक साथ हज़ार सूर्य उदय हों तो जो प्रकाश हो, वह उस महात्मा (विश्वरूप) के तेज के समान होगा।`,
  },
  '9:33': {
    explanation: `।।9.33।। जो पवित्र आचरणवाले ब्राह्मण और ऋषिस्वरूप क्षत्रिय भगवान्  के भक्त हों, वे परमगतिको प्राप्त हो जायँ, इसमें तो कहना ही क्या है। इसलिये इस अनित्य और सुखरहित शरीरको प्राप्त करके तू मेरा भजन कर।`,
  },
  '9:34': {
    explanation: `हे पार्थ! जो तुमने देखा वह मेरी योगमाया से प्रकट किया गया था। अब मैं तुम्हें अपना शाश्वत रूप बताता हूँ।`,
  },
  '10:1': {
    explanation: `हे गुडाकेश! मैं सभी प्राणियों के हृदय में स्थित आत्मा हूँ। मैं ही सभी प्राणियों का आदि, मध्य और अंत हूँ।`,
  },
  '10:2': {
    explanation: `हे पार्थ! जो तुमने देखा वह मेरी योगमाया से प्रकट किया गया था। अब मैं तुम्हें अपना शाश्वत रूप बताता हूँ।`,
  },
  '10:3': {
    explanation: `हे भारत! प्रत्येक व्यक्ति की श्रद्धा उसके स्वभाव (सत्त्व) के अनुसार होती है। यह पुरुष श्रद्धामय है — जैसी श्रद्धा, वैसा पुरुष।`,
  },
  '10:4': {
    explanation: `।।10.4 -- 10.5।। बुद्धि, ज्ञान, असम्मोह, क्षमा, सत्य, दम, शम, सुख, दुःख, भव, अभाव, भय, अभय, अहिंसा, समता, तुष्टि, तप, दान, यश और अपयश -- प्राणियोंके ये अनेक प्रकारके और अलग-अलग (बीस) भाव मेरेसे ही होते हैं।`,
  },
  '10:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '10:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '10:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '10:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '10:9': {
    explanation: `।।10.9।।। मेरेमें चित्तवाले, मेरेमें प्राणोंको अर्पण करनेवाले भक्तजन आपसमें मेरे गुण, प्रभाव आदिको जानते हुए और उनका कथन करते हुए ही नित्य-निरन्तर सन्तुष्ट रहते हैं और मेरेमें प्रेम करते हैं।`,
  },
  '10:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '10:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '10:12': {
    explanation: `।।10.12 -- 10.12।। अर्जुन बोले -- परम ब्रह्म, परम धाम और महान् पवित्र आप ही हैं। आप शाश्वत, दिव्य पुरुष, आदिदेव, अजन्मा और विभु (व्यापक) हैं -- ऐसा सब-के-सब ऋषि, देवर्षि नारद, असित, देवल तथा व्यास कहते हैं और स्वयं आप भी मेरे प्रति कहते हैं।`,
  },
  '10:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '10:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '10:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '10:16': {
    explanation: `।।10.16।।  जिन विभूतियोंसे आप इन सम्पूर्ण लोकोंको व्याप्त करके स्थित हैं, उन सभी अपनी दिव्य विभूतियोंका सम्पूर्णतासे वर्णन करनेमें आप ही समर्थ हैं।`,
  },
  '10:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '10:18': {
    explanation: `।।10.18।। हे जनार्दन ! आप अपने योग (सामर्थ्य) को और विभूतियोंको विस्तारसे फिर कहिये; क्योंकि आपके अमृतमय वचन सुनते-सुनते मेरी तृप्ति नहीं हो रही है।`,
  },
  '10:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '10:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '10:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '10:23': {
    explanation: `।।10.23।। रुद्रोंमें शंकर और यक्ष-राक्षसोंमें कुबेर मैं हूँ।वसुओंमें पावक (अग्नि) और शिखरवाले पर्वतोंमें सुमेरु मैं हूँ।`,
  },
  '10:24': {
    explanation: `।।10.24।। हे पार्थ ! पुरोहितोंमें मुख्य बृहस्पतिको मेरा स्वरूप समझो। सेनापतियोंमें स्कन्द और जलाशयोंमें समुद्र मैं हूँ।`,
  },
  '10:25': {
    explanation: `।।10.25।। महर्षियोंमें भृगु और वाणियों-(शब्दों-) में एक अक्षर अर्थात् प्रणव मैं हूँ। सम्पूर्ण यज्ञोंमें जपयज्ञ और स्थिर रहनेवालोंमें हिमालय मैं हूँ।`,
  },
  '10:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '10:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '10:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '10:29': {
    explanation: `।।10.29।। नागोंमें अनन्त (शेषनाग) और जल-जन्तुओंका अधिपति वरुण मैं हूँ। पितरोंमें अर्यमा और शासन करनेवालोंमें यमराज मैं हूँ।`,
  },
  '10:31': {
    explanation: `हे केशव! मैं अपशकुन ही देख रहा हूँ। युद्ध में स्वजनों को मारने में मुझे कोई कल्याण नहीं दिखता।`,
  },
  '10:32': {
    explanation: `आकाश में एक साथ हज़ार सूर्य उदय हों तो जो प्रकाश हो, वह उस महात्मा (विश्वरूप) के तेज के समान होगा।`,
  },
  '10:33': {
    explanation: `।।10.33।। अक्षरोंमें अकार और समासोंमें द्वन्द्व समास मैं हूँ। अक्षयकाल अर्थात् कालका भी महाकाल तथा सब ओर मुखवाला धाता भी मैं हूँ।`,
  },
  '10:35': {
    explanation: `अपने स्वधर्म में मरना भला है, चाहे वह अपूर्ण हो; परधर्म को अच्छी तरह से करना भयावह है।`,
  },
  '10:36': {
    explanation: `।।10.36।। छल करनेवालोंमें जूआ और तेजस्वियोंमें तेज मैं हूँ। जीतनेवालोंकी विजय, निश्चय करनेवालोंका निश्चय और सात्त्विक मनुष्योंका सात्त्विक भाव मैं हूँ।`,
  },
  '10:37': {
    explanation: `।।10.37।। वृष्णिवंशियोंमें वासुदेव और पाण्डवोंमें धनञ्जय मैं हूँ। मुनियोंमें वेदव्यास और कवियोंमें कवि शुक्राचार्य भी मैं हूँ।`,
  },
  '10:38': {
    explanation: `सुख-दुःख, लाभ-हानि और जय-पराजय को समान करके तब युद्ध के लिए तैयार हो। इस प्रकार तुम पाप नहीं प्राप्त करोगे।`,
  },
  '10:39': {
    explanation: `।।10.39।। हे अर्जुन! सम्पूर्ण प्राणियोंका जो बीज है, वह बीज मैं ही हूँ; क्योंकि मेरे बिना कोई भी चर-अचर प्राणी नहीं है अर्थात् चर-अचर सब कुछ मैं ही हूँ।`,
  },
  '10:40': {
    explanation: `।।10.40।। हे परंतप अर्जुन ! मेरी दिव्य विभूतियोंका अन्त नहीं है। मैंने तुम्हारे सामने अपनी विभूतियोंका जो विस्तार कहा है, यह तो केवल संक्षेपसे कहा है।`,
  },
  '10:41': {
    explanation: `।।10.41।। जो-जो ऐश्वर्ययुक्त, शोभायुक्त और बलयुक्त प्राणी तथा वस्तु है, उस-उसको तुम मेरे ही तेज-(योग-) के अंशसे उत्पन्न हुई समझो।`,
  },
  '10:42': {
    explanation: `जो-जो आचरण श्रेष्ठ पुरुष करता है, अन्य लोग भी वही करते हैं। वह जो प्रमाण स्थापित करता है, संसार उसी का अनुसरण करता है।`,
  },
  '11:1': {
    explanation: `आकाश में एक साथ हज़ार सूर्य उदय हों तो जो प्रकाश हो, वह उस महात्मा (विश्वरूप) के तेज के समान होगा।`,
  },
  '11:2': {
    explanation: `और हे भारत! सभी क्षेत्रों में क्षेत्रज्ञ (क्षेत्र को जानने वाला) भी मुझे ही जानो। क्षेत्र और क्षेत्रज्ञ का यह ज्ञान ही मेरे मत में सच्चा ज्ञान है।`,
  },
  '11:3': {
    explanation: `हे भारत! प्रत्येक व्यक्ति की श्रद्धा उसके स्वभाव (सत्त्व) के अनुसार होती है। यह पुरुष श्रद्धामय है — जैसी श्रद्धा, वैसा पुरुष।`,
  },
  '11:4': {
    explanation: `।।11.4।। हे प्रभो ! मेरे द्वारा आपका वह परम ऐश्वर रूप देखा जा सकता है -- ऐसा अगर आप मानते हैं, तो हे योगेश्वर ! आप अपने उस अविनाशी स्वरूपको मुझे दिखा दीजिये।`,
  },
  '11:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '11:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '11:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '11:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '11:9': {
    explanation: `।।11.9।। सञ्जय बोले -- हे राजन् ! ऐसा कहकर फिर महायोगेश्वर भगवान् श्रीकृष्णने अर्जुनको परम ऐश्वर-रूप दिखाया।`,
  },
  '11:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '11:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '11:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '11:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '11:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '11:16': {
    explanation: `।।11.16।। हे विश्वरूप ! हे विश्वेश्वरव ! आपको मैं अनेक हाथों, पेटों, मुखों और नेत्रोंवाला तथा सब ओरसे अनन्त रूपोंवाला देख रहा हूँ। मैं आपके न आदिको, न मध्यको और न अन्तको ही देख रहा हूँ।`,
  },
  '11:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '11:18': {
    explanation: `।।11.18।। आप ही जाननेयोग्य परम अक्षर (अक्षरब्रह्म) हैं, आप ही इस सम्पूर्ण विश्वके परम आश्रय हैं, आप ही सनातनधर्मके रक्षक हैं और आप ही अविनाशी सनातन पुरुष हैं -- ऐसा मैं मानता हूँ।`,
  },
  '11:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '11:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '11:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '11:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '11:23': {
    explanation: `।।11.23।। हे महाबाहो! आपके बहुत मुखों और नेत्रोंवाले, बहुत भुजाओं, जंघाओं और चरणोंवाले, बहुत उदरोंवाले, बहुत विकराल दाढ़ोंवाले महान् रूपको देखकर सब प्राणी व्यथित हो रहे हैं तथा मैं भी व्यथित हो रहा हूँ।`,
  },
  '11:24': {
    explanation: `।।11.24।। हे विष्णो ! आपके अनेक देदीप्यमान वर्ण हैं, आप आकाशको स्पर्श कर रहे हैं, आपका मुख फैला हुआ है आपके नेत्र प्रदीप्त और विशाल हैं। ऐसे आपको देखकर भयभीत अन्तःकरणवाला मैं धैर्य और शान्तिको प्राप्त नहीं हो रहा हूँ।`,
  },
  '11:25': {
    explanation: `।।11.25।। आपके प्रलयकालकी अग्निके समान प्रज्वलित और दाढ़ोंके कारण विकराल (भयानक) मुखोंको देखकर मुझे न तो दिशाओंका ज्ञान हो रहा है और न शान्ति ही मिल रही है। इसलिये हे देवेश ! हे जगन्निवास ! आप प्रसन्न होइये।`,
  },
  '11:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '11:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '11:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '11:29': {
    explanation: `।।11.29।। जैसे पतंगे मोहवश अपना नाश करनेके लिये बड़े वेगसे दौड़ते हुए प्रज्वलित अग्निमें प्रविष्ट होते हैं, ऐसे ही ये सब लोग भी मोहवश अपना नाश करनेके लिये बड़े वेगसे दौड़ते हुए आपके मुखोंमें प्रविष्ट हो रहे हैं।`,
  },
  '11:31': {
    explanation: `हे केशव! मैं अपशकुन ही देख रहा हूँ। युद्ध में स्वजनों को मारने में मुझे कोई कल्याण नहीं दिखता।`,
  },
  '11:33': {
    explanation: `।।11.33।। इसलिये तुम युद्धके लिये खड़े हो जाओ और यशको प्राप्त करो तथा शत्रुओंको जीतकर धन-धान्यसे सम्पन्न राज्यको भोगो। ये सभी मेरे द्वारा पहलेसे ही मारे हुए हैं। हे सव्यसाचिन् !  तुम निमित्तमात्र बन जाओ।`,
  },
  '11:34': {
    explanation: `हे पार्थ! जो तुमने देखा वह मेरी योगमाया से प्रकट किया गया था। अब मैं तुम्हें अपना शाश्वत रूप बताता हूँ।`,
  },
  '11:35': {
    explanation: `अपने स्वधर्म में मरना भला है, चाहे वह अपूर्ण हो; परधर्म को अच्छी तरह से करना भयावह है।`,
  },
  '11:36': {
    explanation: `।।11.36।। अर्जुन बोले -- हे अन्तर्यामी भगवन् ! आपके नाम, गुण, लीलाका कीर्तन करनेसे यह सम्पूर्ण जगत् हर्षित हो रहा है और अनुराग(-प्रेम-) को प्राप्त हो रहा है। आपके नाम, गुण आदिके कीर्तनसे भयभीत होकर राक्षसलोग दसों दिशाओंमें भागते हुए जा रहे हैं और सम्पूर्ण सिद्धगण आपको नमस्कार कर रहे हैं। यह सब होना उचित ही है।`,
  },
  '11:37': {
    explanation: `।।11.37।। हे महात्मन् ! गुरुओंके भी गुरु और ब्रह्माके भी आदिकर्ता आपके लिये (वे सिद्धगण) नमस्कार क्यों नहीं करें? क्योंकि हे अनन्त ! हे देवेश ! हे जगन्निवास ! आप अक्षरस्वरूप हैं; आप सत् भी हैं, असत् भी हैं, और सत्-असत् से पर भी जो कुछ है, वह भी आप ही हैं।`,
  },
  '11:38': {
    explanation: `सुख-दुःख, लाभ-हानि और जय-पराजय को समान करके तब युद्ध के लिए तैयार हो। इस प्रकार तुम पाप नहीं प्राप्त करोगे।`,
  },
  '11:39': {
    explanation: `।।11.39।। आप ही वायु, यमराज, अग्नि, वरुण, चन्द्रमा, दक्ष आदि प्रजापति और प्रपितामह (ब्रह्माजीके भी पिता) हैं। आपको हजारों बार नमस्कार हो! नमस्कार हो ! ! और फिर भी आपको बार-बार नमस्कार हो ! नमस्कार हो !`,
  },
  '11:40': {
    explanation: `।।11.40।। हे सर्व ! आपको आगेसे भी नमस्कार हो !  पीछेसे भी नमस्कार हो ! सब ओरसे ही नमस्कार हो ! हे अनन्तवीर्य ! अमित विक्रमवाले आपने सबको समावृत कर रखा है; अतः सब कुछ आप ही हैं।`,
  },
  '11:41': {
    explanation: `।।11.41 -- 11.42।। आपकी महिमा और स्वरूपको न जानते हुए 'मेरे सखा हैं' ऐसा मानकर मैंने प्रमादसे अथवा प्रेमसे हठपूर्वक (बिना सोचे-समझे) 'हे कृष्ण ! हे यादव ! हे सखे !' इस प्रकार जो कुछ कहा है; और हे अच्युत ! हँसी-दिल्लगीमें, चलते-फिरते, सोते-जागते, उठते-बैठते, खाते-पीते समयमें अकेले अथवा उन सखाओं, कुटुम्बियों आदिके सामने मेरे द्वारा आपका जो कुछ तिरस्कार किया गया है;  वह सब अप्रमेयस्वरुप आपसे मैं क्षमा माँगता हूँ।`,
  },
  '11:42': {
    explanation: `जो-जो आचरण श्रेष्ठ पुरुष करता है, अन्य लोग भी वही करते हैं। वह जो प्रमाण स्थापित करता है, संसार उसी का अनुसरण करता है।`,
  },
  '11:43': {
    explanation: `।।11.43।। आप ही इस चराचर संसारके पिता हैं, आप ही पूजनीय हैं और आप ही गुरुओंके महान् गुरु हैं। हे अनन्त प्रभावशाली भगवन् ! इस त्रिलोकीमें आपके समान भी दूसरा कोई नहीं है, फिर अधिक तो हो ही कैसे सकता है !`,
  },
  '11:44': {
    explanation: `।।11.44।। इसलिये शरीरसे लम्बा पड़कर स्तुति करनेयोग्य आप ईश्वरको मैं प्रणाम करके प्रसन्न करना चाहता हूँ। जैसे पिता पुत्रके, मित्र मित्रके और पति पत्नीके अपमानको सह लेता है, ऐसे ही हे देव ! आप मेरे द्वारा किया गया अपमान सहनेमें समर्थ हैं।`,
  },
  '11:45': {
    explanation: `।।11.45।। मैंने ऐसा रुप पहले कभी नहीं देखा। इस रूपको देखकर मैं हर्षित हो रहा हूँ और (साथ-ही-साथ) भयसे मेरा मन अत्यन्त व्यथित हो रहा है। अतः आप मुझे अपने उसी देवरूपको (सौम्य विष्णुरूपको)  दिखाइये। हे देवेश ! हे जगन्निवास ! आप प्रसन्न होइये।`,
  },
  '11:46': {
    explanation: `यदि धार्तराष्ट्र शस्त्र-पाणि होकर युद्ध में मुझ अप्रतिकार करने वाले को मार दें, तो यह मेरे लिए अधिक कल्याणकारक होगा।`,
  },
  '11:47': {
    explanation: `संजय बोले — इस प्रकार कहकर, शोक से व्याकुल मन वाले अर्जुन ने रणभूमि में अपने बाण और धनुष छोड़कर रथ के पिछले भाग में बैठ गए।`,
  },
  '11:48': {
    explanation: `।।11.48।। हे कुरुप्रवीर! मनुष्यलोकमें इस प्रकारके विश्वरूपवाला मैं न वेदोंके पढ़नेसे, न यज्ञोंके अनुष्ठानसे, न दानसे, न उग्र तपोंसे और न मात्र क्रियाओंसे तेरे (कृपापात्रके) सिवाय और किसीके द्वारा देखा जाना शक्य हूँ।`,
  },
  '11:49': {
    explanation: `।।11.49।। यह इस प्रकारका मेरा घोररूप देखकर तेरेको व्यथा नहीं होनी चाहिये और मूढ़भाव भी नहीं होना चाहिये। अब निर्भय और प्रसन्न मनवाला होकर तू फिर उसी मेरे इस (चतुर्भुज) रूपको अच्छी तरह देख ले।`,
  },
  '11:50': {
    explanation: `।।11.50।। सञ्जय बोले -- वासुदेवभगवान् ने अर्जुनसे ऐसा कहकर फिर उसी प्रकारसे अपना रूप (देवरूप) दिखाया और महात्मा श्रीकृष्णने पुनः सौम्यवपु (द्विभुजरूप) होकर इस भयभीत अर्जुनको आश्वासन दिया।`,
  },
  '11:51': {
    explanation: `।।11.51।। अर्जुन बोले -- हे जनार्दन ! आपके इस सौम्य मनुष्यरूपको देखकर मैं इस समय स्थिरचित्त हो गया हूँ और अपनी स्वाभाविक स्थितिको प्राप्त हो गया हूँ।`,
  },
  '11:52': {
    explanation: `।।11.52।। श्रीभगवान् बोले -- मेरा यह जो रूप तुमने देखा है, इसके दर्शन अत्यन्त ही दुर्लभ हैं। इस रूपको देखनेके लिये देवता भी नित्य लालायित रहते हैं।`,
  },
  '11:53': {
    explanation: `।।11.53।। जिस प्रकार तुमने मुझे देखा है, इस प्रकारका (चतुर्भुजरूपवाला) मैं न तो वेदोंसे, न तपसे, न दानसे और न यज्ञसे ही देखा जा सकता हूँ।`,
  },
  '11:54': {
    explanation: `।।11.54।। परन्तु हे शत्रुतापन अर्जुन ! इस प्रकार (चतुर्भुजरूपवाला) मैं अनन्यभक्तिसे ही तत्त्वसे जाननेमें, सगुणरूपसे देखनेमें और प्राप्त करनेमें शक्य हूँ।`,
  },
  '11:55': {
    explanation: `।।11.55।। हे पाण्डवन ! जो मेरे लिये ही कर्म करनेवाला, मेरे ही परायण और मेरा ही भक्त है तथा सर्वथा आसक्तिरहित और प्राणिमात्रके साथ निर्वैर है, वह भक्त मेरेको प्राप्त होता है।`,
  },
  '12:1': {
    explanation: `जो शत्रु और मित्र में, मान और अपमान में, सर्दी-गर्मी और सुख-दुःख में समद्र्शी हो, और आसक्ति से रहित हो — वह भक्त मुझे प्रिय है।`,
  },
  '12:2': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '12:3': {
    explanation: `जो अक्षर, अनिर्देश्य, अव्यक्त, सर्वव्यापी, अचिंत्य, अचल और ध्रुव की उपासना करते हैं...`,
  },
  '12:4': {
    explanation: `।।12.4।।जो अपनी इन्द्रियोंको वशमें करके अचिन्त्य, सब जगह परिपूर्ण, अनिर्देश्य, कूटस्थ, अचल, ध्रुव, अक्षर और अव्यक्तकी उपासना करते हैं, वे प्राणिमात्रके हितमें रत और सब जगह समबुद्धिवाले मनुष्य मुझे ही प्राप्त होते हैं।`,
  },
  '12:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '12:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '12:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '12:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '12:9': {
    explanation: `।।12.9।।अगर तू मनको मेरेमें अचलभावसे स्थिर (अर्पण) करनेमें समर्थ नहीं है, तो हे धनञ्जय ! अभ्यासयोगके द्वारा तू मेरी प्राप्तिकी इच्छा कर।`,
  },
  '12:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '12:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '12:12': {
    explanation: `।।12.12।।अभ्याससे शास्त्रज्ञान श्रेष्ठ है, शास्त्रज्ञानसे ध्यान श्रेष्ठ है और ध्यानसे भी सब कर्मोंके फलका त्याग श्रेष्ठ है। कर्मफलत्यागसे तत्काल ही परमशान्ति प्राप्त हो जाती है।`,
  },
  '12:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '12:16': {
    explanation: `।।12.16।।जो आकाङ्क्षासे रहित, बाहर-भीतरसे पवित्र, दक्ष, उदासीन, व्यथासे रहित और सभी आरम्भोंका अर्थात् नये-नये कर्मोंके आरम्भका सर्वथा त्यागी है, वह मेरा भक्त मुझे प्रिय है।`,
  },
  '12:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '12:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '12:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '13:1': {
    explanation: `और हे भारत! सभी क्षेत्रों में क्षेत्रज्ञ (क्षेत्र को जानने वाला) भी मुझे ही जानो। क्षेत्र और क्षेत्रज्ञ का यह ज्ञान ही मेरे मत में सच्चा ज्ञान है।`,
  },
  '13:4': {
    explanation: `जो सभी प्राणियों में समान रूप से स्थित परमेश्वर को देखता है, नाशवान में अविनाशी को देखता है — वही वास्तव में देखता है।`,
  },
  '13:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '13:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '13:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '13:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '13:9': {
    explanation: `।।13.9।।इन्द्रियोंके विषयोंमें वैराग्यका होना, अहंकारका भी न होना और जन्म, मृत्यु, वृद्धावस्था तथा व्याधियोंमें दुःखरूप दोषोंको बार-बार देखना।`,
  },
  '13:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '13:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '13:12': {
    explanation: `।।13.12।।अध्यात्मज्ञानमें नित्य-निरन्तर रहना, तत्त्वज्ञानके अर्थरूप परमात्माको सब जगह देखना -- यह (पूर्वोक्त साधन-समुदाय) तो ज्ञान है; और जो इसके विपरीत है वह अज्ञान है -- ऐसा कहा गया है।`,
  },
  '13:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '13:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '13:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '13:16': {
    explanation: `।।13.16।।वे परमात्मा सम्पूर्ण प्राणियोंके बाहर-भीतर परिपूर्ण हैं और चर-अचर प्राणियोंके रूपमें भी वे ही हैं एवं दूर-से-दूर तथा नजदीक-से-नजदीक भी वे ही हैं। वे अत्यन्त सूक्ष्म होनेसे जाननेका विषय नहीं हैं।`,
  },
  '13:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '13:18': {
    explanation: `।।13.18।।वह परमात्मा सम्पूर्ण ज्योतियोंका भी ज्योति और अज्ञानसे अत्यन्त परे कहा गया है। वह ज्ञानस्वरूप, जाननेयोग्य, ज्ञान(साधन-समुदाय) से प्राप्त करनेयोग्य और सबके हृदयमें विराजमान है।`,
  },
  '13:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '13:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '13:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '13:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '13:23': {
    explanation: `।।13.23।।यह पुरुष प्रकृति-(शरीर-) के साथ सम्बन्ध रखनेसे 'उपद्रष्टा', उसके साथ मिलकर सम्मति, अनुमति देनेसे 'अनुमन्ता', अपनेको उसका भरणपोषण करनेवाला माननेसे 'भर्ता', उसके सङ्गसे सुखदुःख भोगनेसे 'भोक्ता', और अपनेको उसका स्वामी माननेसे 'महेश्वर' बन जाता है। परन्तु स्वरूपसे यह पुरुष 'परमात्मा' कहा जाता है। यह देहमें रहता हुआ भी देहसे पर (सम्बन्ध-रहित) ही है। `,
  },
  '13:24': {
    explanation: `।।13.24।।इस प्रकार पुरुषको और गुणोंके सहित प्रकृतिको जो मनुष्य अलग-अलग जानता है, वह सब तरहका बर्ताव करता हुआ भी फिर जन्म नहीं लेता।`,
  },
  '13:25': {
    explanation: `।।13.25।।कई मनुष्य ध्यानयोगके द्वारा, कई सांख्ययोगके द्वारा और कई कर्मयोगके द्वारा अपने-आपसे अपने-आपमें परमात्मतत्त्वका अनुभव करते हैं।`,
  },
  '13:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '13:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '13:29': {
    explanation: `।।13.29।।क्योंकि सब जगह समरूपसे स्थित ईश्वरको समरूपसे देखनेवाला मनुष्य अपने-आपसे अपनी हिंसा नहीं करता, इसलिये वह परमगतिको प्राप्त हो जाता है।`,
  },
  '13:31': {
    explanation: `हे केशव! मैं अपशकुन ही देख रहा हूँ। युद्ध में स्वजनों को मारने में मुझे कोई कल्याण नहीं दिखता।`,
  },
  '13:32': {
    explanation: `आकाश में एक साथ हज़ार सूर्य उदय हों तो जो प्रकाश हो, वह उस महात्मा (विश्वरूप) के तेज के समान होगा।`,
  },
  '13:33': {
    explanation: `।।13.33।।जैसे सब जगह व्याप्त आकाश अत्यन्त सूक्ष्म होनेसे कहीं भी लिप्त नहीं होता, ऐसे ही सब जगह परिपूर्ण आत्मा किसी भी देहमें लिप्त नहीं होता।`,
  },
  '13:34': {
    explanation: `हे पार्थ! जो तुमने देखा वह मेरी योगमाया से प्रकट किया गया था। अब मैं तुम्हें अपना शाश्वत रूप बताता हूँ।`,
  },
  '13:35': {
    explanation: `अपने स्वधर्म में मरना भला है, चाहे वह अपूर्ण हो; परधर्म को अच्छी तरह से करना भयावह है।`,
  },
  '14:1': {
    explanation: `हे महाबाहो! सत्त्व, रज और तम — ये प्रकृति से उत्पन्न तीन गुण अव्यय देही (आत्मा) को शरीर में बाँधते हैं।`,
  },
  '14:2': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '14:3': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '14:4': {
    explanation: `।।14.4।।हे कुन्तीनन्दन ! सम्पूर्ण योनियोंमें प्राणियोंके जितने शरीर पैदा होते हैं, उन सबकी मूल प्रकृति तो माता है और मैं बीज-स्थापन करनेवाला पिता हूँ।`,
  },
  '14:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '14:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '14:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '14:9': {
    explanation: `।।14.9।।हे भरतवंशोद्भव अर्जुन ! सत्त्वगुण सुखमें और रजोगुण कर्ममें लगाकर मनुष्यपर विजय करता है तथा तमोगुण ज्ञानको ढककर एवं प्रमादमें भी लगाकर मनुष्यपर विजंय करता है।`,
  },
  '14:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '14:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '14:12': {
    explanation: `।।14.12।।हे भरतवंशमें श्रेष्ठ अर्जुन ! रजोगुणके बढ़नेपर लोभ, प्रवृत्ति, कर्मोंका आरम्भ, अशान्ति और स्पृहा -- ये वृत्तियाँ पैदा होती हैं।`,
  },
  '14:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '14:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '14:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '14:16': {
    explanation: `।।14.16।।(विवेकी पुरुषोंने) शुभ-कर्मका तो सात्त्विक निर्मल फल कहा है, राजस कर्मका फल दुःख कहा है और तामस कर्मका फल अज्ञान (मूढ़ता) कहा है।`,
  },
  '14:18': {
    explanation: `।।14.18।।सत्त्वगुणमें स्थित मनुष्य ऊर्ध्वलोकोंमें जाते हैं, रजोगुणमें स्थित मनुष्य मृत्युलोकमें जन्म लेते हैं और निन्दनीय तमोगुणकी वृत्तिमें स्थित मनुष्य अधोगतिमें जाते हैं।`,
  },
  '14:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '14:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '14:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '14:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '14:23': {
    explanation: `।।14.23।।जो उदासीनकी तरह स्थित है और जो गुणोंके द्वारा विचलित नहीं किया जा सकता तथा गुण ही (गुणोंमें) बरत रहे हैं -- इस भावसे जो अपने स्वरूपमें ही स्थित रहता है और स्वयं कोई भी चेष्टा नहीं करता।`,
  },
  '14:24': {
    explanation: `।।14.24।।जो धीर मनुष्य सुख-दुःखमें सम तथा अपने स्वरूपमें स्थित रहता है; जो मिट्टीके ढेले, पत्थर और सोनेमें सम रहता है जो प्रिय-अप्रियमें तथा अपनी निन्दा-स्तुतिमें सम रहता है; जो मान-अपमानमें तथा मित्र-शत्रुके पक्षमें सम रहता है जो सम्पूर्ण कर्मोंके आरम्भका त्यागी है, वह मनुष्य गुणातीत कहा जाता है।`,
  },
  '14:25': {
    explanation: `।।14.25।।जो धीर मनुष्य सुख-दुःखमें सम तथा अपने स्वरूपमें स्थित रहता है; जो मिट्टीके ढेले, पत्थर और सोनेमें सम रहता है जो प्रिय-अप्रियमें तथा अपनी निन्दा-स्तुतिमें सम रहता है जो मान-अपमानमें तथा मित्र-शत्रुके पक्षमें सम रहता है; जो सम्पूर्ण कर्मोंके आरम्भका त्यागी है, वह मनुष्य गुणातीत कहा जाता है।`,
  },
  '14:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '15:2': {
    explanation: `जीव-जगत में जीव मेरा ही सनातन अंश है। वह प्रकृति में स्थित मन सहित छः इन्द्रियों को अपनी ओर खींचता है।`,
  },
  '15:3': {
    explanation: `मैं सभी प्राणियों के हृदय में निहित हूँ। मुझसे ही स्मृति, ज्ञान और अपोहन (संशय-निवृत्ति) होते हैं। सभी वेदों से केवल मैं ही जानने योग्य हूँ। वेदान्त का कर्ता और वेद को जानने वाला भी मैं ही हूँ।`,
  },
  '15:4': {
    explanation: `।।15.4।।उसके बाद उस परमपद-(परमात्मा-) की खोज करनी चाहिये जिसको प्राप्त होनेपर मनुष्य फिर लौटकर संसारमें नहीं आते और जिससे अनादिकालसे चली आनेवाली यह सृष्टि विस्तारको प्राप्त हुई है, उस आदिपुरुष परमात्माके ही मैं शरण हूँ।`,
  },
  '15:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '15:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '15:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '15:9': {
    explanation: `।।15.9।।यह जीवात्मा मनका आश्रय लेकर श्रोत्र, नेत्र, त्वचा, रसना और घ्राण -- इन पाँचों इन्द्रियोंके द्वारा विषयोंका सेवन करता है।`,
  },
  '15:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '15:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '15:12': {
    explanation: `।।15.12।।सूर्यमें आया हुआ जो तेज सम्पूर्ण जगत् को प्रकाशित करता है और जो तेज चन्द्रमामें है तथा जो तेज अग्निमें है, उस तेजको मेरा ही जान।`,
  },
  '15:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '15:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '15:16': {
    explanation: `।।15.16।।इस संसारमें क्षर (नाशवान्) और अक्षर (अविनाशी) -- ये दो प्रकारके पुरुष हैं। सम्पूर्ण प्राणियोंके शरीर नाशवान् और कूटस्थ (जीवात्मा) अविनाशी कहा जाता है। `,
  },
  '15:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '15:18': {
    explanation: `।।15.18।।मैं क्षरसे अतीत हूँ और अक्षरसे भी उत्तम हूँ, इसलिये लोकमें और वेदमें पुरुषोत्तम नामसे प्रसिद्ध हूँ।`,
  },
  '15:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '15:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '16:2': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '16:3': {
    explanation: `हे भारत! प्रत्येक व्यक्ति की श्रद्धा उसके स्वभाव (सत्त्व) के अनुसार होती है। यह पुरुष श्रद्धामय है — जैसी श्रद्धा, वैसा पुरुष।`,
  },
  '16:4': {
    explanation: `।।16.4।।हे पृथानन्दन ! दम्भ करना, घमण्ड करना, अभिमान करना, क्रोध करना, कठोरता रखना और अविवेकका होना भी -- ये सभी आसुरीसम्पदाको प्राप्त हुए मनुष्यके लक्षण हैं।`,
  },
  '16:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '16:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '16:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '16:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '16:9': {
    explanation: `।।16.9।।उपर्युक्त (नास्तिक) दृष्टिका आश्रय लेनेवाले जो मनुष्य अपने नित्य स्वरूपको नहीं मानते, जिनकी बुद्धि तुच्छ है, जो उग्रकर्मा और संसारके शत्रु हैं, उन मनुष्योंकी सामर्थ्यका उपयोग जगत्का नाश करनेके लिये ही होता है।`,
  },
  '16:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '16:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '16:12': {
    explanation: `।।16.12।।वे आशाकी सैकड़ों फाँसियोंसे बँधे हुए मनुष्य काम-क्रोधके परायण होकर पदार्थोंका भोग करनेके लिये अन्यायपूर्वक धन-संचय करनेकी चेष्टा करते रहते हैं।`,
  },
  '16:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '16:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '16:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '16:16': {
    explanation: `।।16.16।।कामनाओंके कारण तरह-तरहसे भ्रमित चित्तवाले, मोह-जालमें अच्छी तरहसे फँसे हुए तथा पदार्थों और भोगोंमें अत्यन्त आसक्त रहनेवाले मनुष्य भयङ्कर नरकोंमें गिरते हैं।`,
  },
  '16:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '16:18': {
    explanation: `।।16.18।।वे अहङ्कार, हठ, घमण्ड, कामना और क्रोधका आश्रय लेनेवाले मनुष्य अपने और दूसरोंके शरीरमें रहनेवाले मुझ अन्तर्यामीके साथ द्वेष करते हैं तथा (मेरे और दूसरोंके गुणोंमें) दोष-दृष्टि रखते हैं।`,
  },
  '16:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '16:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '16:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '16:23': {
    explanation: `।।16.23।। जो मनुष्य शास्त्रविधिको छोड़कर अपनी इच्छासे मनमाना आचरण करता है, वह न सिद्धि-(अन्तःकरणकी शुद्धि-) को, न सुखको और न परमगतिको ही प्राप्त होता है।`,
  },
  '16:24': {
    explanation: `।।16.24।।अतः तेरे लिये कर्तव्य-अकर्तव्यकी व्यवस्थामें शास्त्र ही प्रमाण है -- ऐसा जानकर तू इस लोकमें शास्त्र-विधिसे नियत कर्तव्य कर्म करनेयोग्य है।`,
  },
  '17:1': {
    explanation: `हे भारत! प्रत्येक व्यक्ति की श्रद्धा उसके स्वभाव (सत्त्व) के अनुसार होती है। यह पुरुष श्रद्धामय है — जैसी श्रद्धा, वैसा पुरुष।`,
  },
  '17:2': {
    explanation: `जब वह त्रिविध तप (शरीर, वाणी, मन का) श्रेष्ठ श्रद्धा से युक्त और फल की आकांक्षा रहित पुरुषों द्वारा किया जाता है — उसे सात्त्विक तप कहते हैं।`,
  },
  '17:4': {
    explanation: `।।17.4।।सात्त्विक मनुष्य देवताओंका पूजन करते हैं, राजस मनुष्य यक्षों और राक्षसोंका और दूसरे जो तामस मनुष्य हैं, वे प्रेतों और भूतगणोंका पूजन करते हैं।`,
  },
  '17:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '17:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '17:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '17:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '17:9': {
    explanation: `।।17.9।।अति कड़वे, अति खट्टे, अति नमकीन, अति गरम, अति तीखे, अति रूखे और अति दाहकारक आहार अर्थात् भोजनके पदार्थ राजस मनुष्यको प्रिय होते हैं, जो कि दुःख, शोक और रोगोंको देनेवाले हैं।`,
  },
  '17:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '17:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '17:12': {
    explanation: `।।17.12।।परन्तु हे भरतश्रेष्ठ अर्जुन ! जो यज्ञ फलकी इच्छाको लेकर अथवा दम्भ-(दिखावटीपन-) के लिये भी किया जाता है, उसको तुम राजस समझो।`,
  },
  '17:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '17:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '17:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '17:16': {
    explanation: `।।17.16।।मनकी प्रसन्नता, सौम्य भाव, मननशीलता, मनका निग्रह और भावोंकी शुद्धि -- इस तरह यह मन-सम्बन्धी तप कहा जाता है।`,
  },
  '17:18': {
    explanation: `।।17.18।।जो तप सत्कार, मान और पूजाके लिये तथा दिखानेके भावसे किया जाता है, वह इस लोकमें अनिश्चित और नाशवान् फल देनेवाला तप राजस कहा गया है।`,
  },
  '17:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '17:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '17:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '17:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '17:23': {
    explanation: `।।17.23।। ऊँ, तत् और सत् -- इन तीनों नामोंसे जिस परमात्माका निर्देश किया गया है, उसी परमात्माने सृष्टिके आदिमें वेदों, ब्राह्मणों और यज्ञोंकी रचना की है।`,
  },
  '17:24': {
    explanation: `।।17.24।।इसलिये वैदिक सिद्धान्तोंको माननेवाले पुरुषोंकी शास्त्रविधिसे नियत यज्ञ, दान और तपरूप क्रियाएँ सदा 'ऊँ' इस परमात्माके नामका उच्चारण करके ही आरम्भ होती हैं।`,
  },
  '17:25': {
    explanation: `।।17.25।। 'तत्' नामसे कहे जानेवाले परमात्माके लिये ही सब कुछ है -- ऐसा मानकर मुक्ति चाहनेवाले मनुष्योंद्वारा फलकी इच्छासे रहित होकर अनेक प्रकारकी यज्ञ और तपरूप क्रियाएँ तथा दानरूप क्रियाएँ की जाती हैं।`,
  },
  '17:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '17:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '17:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '18:1': {
    explanation: `सभी धर्मों (कर्तव्यों) को छोड़कर मेरी ही शरण में आओ। मैं तुम्हें सम्पूर्ण पापों से मुक्त कर दूँगा, तुम शोक न करो।`,
  },
  '18:2': {
    explanation: `जहाँ योगेश्वर कृष्ण हैं और जहाँ धनुर्धारी अर्जुन हैं, वहीं श्री, विजय, विभूति और अचल नीति है — यही मेरा मत है।`,
  },
  '18:3': {
    explanation: `हे भारत! प्रत्येक व्यक्ति की श्रद्धा उसके स्वभाव (सत्त्व) के अनुसार होती है। यह पुरुष श्रद्धामय है — जैसी श्रद्धा, वैसा पुरुष।`,
  },
  '18:4': {
    explanation: `।।18.4।। हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! तू संन्यास और त्याग -- इन दोनोंमेंसे पहले त्यागके विषयमें मेरा निश्चय सुन; क्योंकि हे पुरुषश्रेष्ठ ! त्याग तीन प्रकारका कहा गया है।`,
  },
  '18:5': {
    explanation: `अपने आपको अपने आपसे ऊपर उठाओ, अपने आपको गिर्फ्तार न करो। मन ही आत्मा का मित्र है और मन ही आत्मा का शत्रु।`,
  },
  '18:6': {
    explanation: `जिसने अपने मन को अपने आप से जीत लिया है, उसके लिए मन ही सर्वश्रेष्ठ मित्र है। जिसने मन को नहीं जीता, वह मन ही शत्रु की भाँति व्यवहार करता है।`,
  },
  '18:7': {
    explanation: `जब-जब भारत! धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं अपना रूप प्रकट करता हूँ।`,
  },
  '18:8': {
    explanation: `साधुओं की रक्षा, दुष्टों के विनाश और धर्म की पुनः स्थापना के लिए मैं युग-युग में प्रकट होता हूँ।`,
  },
  '18:9': {
    explanation: `।।18.9।।हे अर्जुन ! 'केवल कर्तव्यमात्र करना है' -- ऐसा समझकर जो नियत कर्म आसक्ति और फलका त्याग करके किया जाता है, वही सात्त्विक त्याग माना गया है।`,
  },
  '18:10': {
    explanation: `जो मनुष्य सम्पूर्ण कर्मों को ब्रह्म में अर्पित करके और आसक्ति छोड़कर कर्म करता है, वह जल से कमल-पत्र की तरह पाप से लिप्त नहीं होता।`,
  },
  '18:11': {
    explanation: `श्रीकृष्ण बोले — तुम उनके लिए शोक करते हो जो शोक के योग्य नहीं हैं, फिर भी ज्ञान की बातें करते हो। बुद्धिमान न जीवित के लिए शोक करते हैं, न मृत के लिए।`,
  },
  '18:12': {
    explanation: `।।18.12।।कर्मफलका त्याग न करनेवाले मनुष्योंको कर्मोंका इष्ट, अनिष्ट और मिश्रित -- ऐसे तीन प्रकारका फल मरनेके बाद भी होता है; परन्तु कर्मफलका त्याग करनेवालोंको कहीं भी नहीं होता।`,
  },
  '18:13': {
    explanation: `जैसे इस शरीर में जीवात्मा बाल्य, यौवन और वृद्धावस्था को प्राप्त होता है, वैसे ही वह दूसरे शरीर को प्राप्त होता है। धीर पुरुष इसमें मोहित नहीं होते।`,
  },
  '18:14': {
    explanation: `हे कौन्तेय! इन्द्रियों का विषयों से सम्पर्क शीत-उष्ण, सुख-दुःख को देने वाला है। वे आगम-अपायिन (आने-जाने वाले) और अनित्य हैं, उन्हें तू सहन कर।`,
  },
  '18:15': {
    explanation: `जिससे संसार उद्विग्न नहीं होता और जो संसार से उद्विग्न नहीं होता, जो हर्ष, अमर्ष, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।`,
  },
  '18:16': {
    explanation: `।।18.16।।परन्तु ऐसे पाँच हेतुओंके होनेपर भी जो उस (कर्मोंके) विषयमें केवल (शुद्ध) आत्माको कर्ता मानता है, वह दुर्मति ठीक नहीं समझता; क्योंकि उसकी बुद्धि शुद्ध नहीं है।`,
  },
  '18:17': {
    explanation: `सत्त्व से ज्ञान उत्पन्न होता है; रजस से लोभ; और तमस से प्रमाद, मोह और अज्ञान।`,
  },
  '18:18': {
    explanation: `।।18.18।।ज्ञान, ज्ञेय और परिज्ञाता -- इन तीनोंसे कर्मप्रेरणा होती है तथा करण, कर्म और कर्ता -- इन तीनोंसे कर्मसंग्रह होता है।`,
  },
  '18:19': {
    explanation: `इसलिए सदा आसक्ति रहित होकर कर्तव्य-कर्म को भली-भाँति कर। आसक्ति रहित होकर कर्म करता हुआ मनुष्य परंब्रह्म को प्राप्त करता है।`,
  },
  '18:20': {
    explanation: `हनुमान-ध्वज वाले अर्जुन ने युद्ध के लिए अपना धनुष उठाया। प्रतीक और आदर्श मन को साहस देते हैं।`,
  },
  '18:21': {
    explanation: `तीन प्रकार के नर्क के द्वार हैं जो आत्मा का नाश करते हैं — काम (वासना), क्रोध और लोभ। इसलिए इन तीनों को त्यागना चाहिए।`,
  },
  '18:22': {
    explanation: `जो भक्त अनन्य भाव से मेरा चिन्तन करते हुए मेरी उपासना करते हैं, उन नित्य भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।`,
  },
  '18:23': {
    explanation: `।।18.23।।जो कर्म शास्त्रविधिसे नियत किया हुआ और कर्तृत्वाभिमानसे रहित हो तथा फलेच्छारहित मनुष्यके द्वारा बिना राग-द्वेषके किया हुआ हो, वह सात्त्विक कहा जाता है।`,
  },
  '18:24': {
    explanation: `।।18.24।।परन्तु जो कर्म भोगोंको चाहनेवाले मनुष्यके द्वारा अहंकार अथवा परिश्रमपूर्वक किया जाता है, वह राजस कहा गया है।`,
  },
  '18:25': {
    explanation: `।।18.25।।जो कर्म परिणाम, हानि, हिंसा और सामर्थ्यको न देखकर मोहपूर्वक आरम्भ किया जाता है, वह तामस कहा जाता है।`,
  },
  '18:26': {
    explanation: `जो अव्यभिचारी भक्तियोग से मेरी सेवा करता है, वह इन तीनों गुणों को पार करके ब्रह्म-प्राप्ति के योग्य हो जाता है।`,
  },
  '18:27': {
    explanation: `क्योंकि जन्म लेने वाले के लिए मृत्यु निश्चित है, और मृत्यु होने वाले के लिए जन्म निश्चित है। इसलिए इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।`,
  },
  '18:28': {
    explanation: `अर्जुन बोले — हे कृष्ण! युद्ध की इच्छा से खड़े इन स्वजनों को देखकर मेरे अंग शिथिल हो रहे हैं और मुँह सूख रहा है।`,
  },
  '18:29': {
    explanation: `।।18.29।।हे धनञ्जय ! अब तू गुणोंके अनुसार बुद्धि और धृतिके भी तीन प्रकारके भेद अलग-अलगरूपसे सुन, जो कि मेरे द्वारा पूर्णरूपसे कहे जा रहे हैं।`,
  },
  '18:31': {
    explanation: `हे केशव! मैं अपशकुन ही देख रहा हूँ। युद्ध में स्वजनों को मारने में मुझे कोई कल्याण नहीं दिखता।`,
  },
  '18:32': {
    explanation: `आकाश में एक साथ हज़ार सूर्य उदय हों तो जो प्रकाश हो, वह उस महात्मा (विश्वरूप) के तेज के समान होगा।`,
  },
  '18:33': {
    explanation: `।।18.33।।हे पार्थ ! समतासे युक्त जिस अव्यभिचारिणी धृतिके द्वारा मनुष्य मन, प्राण और इन्द्रियोंकी क्रियाओंको धारण करता है, वह धृति सात्त्विकी है।`,
  },
  '18:34': {
    explanation: `हे पार्थ! जो तुमने देखा वह मेरी योगमाया से प्रकट किया गया था। अब मैं तुम्हें अपना शाश्वत रूप बताता हूँ।`,
  },
  '18:35': {
    explanation: `अपने स्वधर्म में मरना भला है, चाहे वह अपूर्ण हो; परधर्म को अच्छी तरह से करना भयावह है।`,
  },
  '18:36': {
    explanation: `।।18.36।।हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! अब तीन प्रकारके सुखको भी तुम मेरेसे सुनो। जिसमें अभ्याससे रमण होता है और जिससे दुःखोंका अन्त हो जाता है, ऐसा वह परमात्मविषयक बुद्धिकी प्रसन्नतासे पैदा होनेवाला जो सुख (सांसारिक आसक्तिके कारण) आरम्भमें विषकी तरह और परिणाममें अमृतकी तरह होता है, वह सुख सात्त्विक कहा गया है।`,
  },
  '18:37': {
    explanation: `।।18.37।।हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! अब तीन प्रकारके सुखको भी तुम मेरेसे सुनो। जिसमें अभ्याससे रमण होता है और जिससे दुःखोंका अन्त हो जाता है, ऐसा वह परमात्मविषयक बुद्धिकी प्रसन्नतासे पैदा होनेवाला जो सुख (सांसारिक आसक्तिके कारण) आरम्भमें विषकी तरह और परिणाममें अमृतकी तरह होता है, वह सुख सात्त्विक कहा गया है।`,
  },
  '18:38': {
    explanation: `सुख-दुःख, लाभ-हानि और जय-पराजय को समान करके तब युद्ध के लिए तैयार हो। इस प्रकार तुम पाप नहीं प्राप्त करोगे।`,
  },
  '18:39': {
    explanation: `।।18.39।।निद्रा, आलस्य और प्रमादसे उत्पन्न होनेवाला जो सुख आरम्भमें और परिणाममें अपनेको मोहित करनेवाला है, वह सुख तामस कहा गया है।`,
  },
  '18:40': {
    explanation: `।।18.40।।पृथ्वीमें या स्वर्गमें अथवा देवताओंमें तथा इनके सिवाय और कहीं भी वह ऐसी कोई वस्तु नहीं है, जो प्रकृतिसे उत्पन्न इन तीनों गुणोंसे रहित हो।`,
  },
  '18:41': {
    explanation: `।।18.41।।हे परंतप ! ब्राह्मण, क्षत्रिय, वैश्य और शूद्रोंके कर्म स्वभावसे उत्पन्न हुए तीनों गुणोंके द्वारा विभक्त किये गये हैं।`,
  },
  '18:42': {
    explanation: `जो-जो आचरण श्रेष्ठ पुरुष करता है, अन्य लोग भी वही करते हैं। वह जो प्रमाण स्थापित करता है, संसार उसी का अनुसरण करता है।`,
  },
  '18:43': {
    explanation: `।।18.43।।शूरवीरता, तेज, धैर्य, प्रजाके संचालन आदिकी विशेष चतुरता, युद्धमें कभी पीठ न दिखाना, दान करना और शासन करनेका भाव -- ये सबकेसब क्षत्रियके स्वाभाविक कर्म हैं।`,
  },
  '18:44': {
    explanation: `।।18.44।।खेती करना, गायोंकी रक्षा करना और शुद्ध व्यापार करना -- ये सब-के-सब वैश्यके स्वाभाविक कर्म हैं, तथा चारों वर्णोंकी सेवा करना शूद्रका भी स्वाभाविक कर्म है।`,
  },
  '18:45': {
    explanation: `।।18.45।।अपने-अपने कर्ममें तत्परतापूर्वक लगा हुआ मनुष्य सम्यक् सिद्धि-(परमात्मा-)को प्राप्त कर लेता है। अपने कर्ममें लगा हुआ मनुष्य जिस प्रकार सिद्धिको प्राप्त होता है? उस प्रकारको तू मेरेसे सुन।`,
  },
  '18:46': {
    explanation: `यदि धार्तराष्ट्र शस्त्र-पाणि होकर युद्ध में मुझ अप्रतिकार करने वाले को मार दें, तो यह मेरे लिए अधिक कल्याणकारक होगा।`,
  },
  '18:47': {
    explanation: `संजय बोले — इस प्रकार कहकर, शोक से व्याकुल मन वाले अर्जुन ने रणभूमि में अपने बाण और धनुष छोड़कर रथ के पिछले भाग में बैठ गए।`,
  },
  '18:48': {
    explanation: `।।18.48।।हे कुन्तीनन्दन ! दोषयुक्त होनेपर भी सहज कर्मका त्याग नहीं करना चाहिये; क्योंकि सम्पूर्ण कर्म धुएँसे अग्निकी तरह किसी-न-किसी दोषसे युक्त हैं।`,
  },
  '18:49': {
    explanation: `।।18.49।।जिसकी बुद्धि सब जगह आसक्तिरहित है, जिसने शरीरको वशमें कर रखा है, जो स्पृहारहित है, वह मनुष्य सांख्ययोगके द्वारा नैष्कर्म्य-सिद्धिको प्राप्त हो जाता है।`,
  },
  '18:50': {
    explanation: `।।18.50।।हे कौन्तेय ! सिद्धि-(अन्तःकरणकी शुद्धि-) को प्राप्त हुआ साधक ब्रह्मको, जो कि ज्ञानकी परा निष्ठा है, जिस प्रकारसे प्राप्त होता है, उस प्रकारको तुम मुझसे संक्षेपमें ही समझो।`,
  },
  '18:51': {
    explanation: `।।18.51।।जो विशुद्ध (सात्त्विकी) बुद्धिसे युक्त, वैराग्यके आश्रित, एकान्तका सेवन करनेवाला और नियमित भोजन करनेवाला साधक धैर्यपूर्वक इन्द्रियोंका नियमन करके, शरीर-वाणी-मनको वशमें करके, शब्दादि विषयोंका त्याग करके और राग-द्वेषको छोड़कर निरन्तर ध्यानयोगके परायण हो जाता है, वह अहंकार, बल, दर्प, काम, क्रोध और परिग्रहका त्याग करके एवं निर्मम तथा शान्त होकर ब्रह्मप्राप्तिका पात्र हो जाता है।`,
  },
  '18:52': {
    explanation: `।।18.52।।जो विशुद्ध (सात्त्विकी) बुद्धिसे युक्त, वैराग्यके आश्रित, एकान्तका सेवन करनेवाला और नियमित भोजन करनेवाला साधक धैर्यपूर्वक इन्द्रियोंका नियमन करके, शरीर-वाणी-मनको वशमें करके, शब्दादि विषयोंका त्याग करके और राग-द्वेषको छोड़कर निरन्तर ध्यानयोगके परायण हो जाता है, वह अहंकार, बल, दर्प, काम, क्रोध और परिग्रहका त्याग करके एवं निर्मम तथा शान्त होकर ब्रह्मप्राप्तिका पात्र हो जाता है।`,
  },
  '18:53': {
    explanation: `।।18.53।।जो विशुद्ध (सात्त्विकी) बुद्धिसे युक्त, वैराग्यके आश्रित, एकान्तका सेवन करनेवाला और नियमित भोजन करनेवाला साधक धैर्यपूर्वक इन्द्रियोंका नियमन करके, शरीर-वाणी-मनको वशमें करके, शब्दादि विषयोंका त्याग करके और राग-द्वेषको छोड़कर निरन्तर ध्यानयोगके परायण हो जाता है, वह अहंकार, बल, दर्प, काम, क्रोध और परिग्रहका त्याग करके एवं निर्मम तथा शान्त होकर ब्रह्मप्राप्तिका पात्र हो जाता है।`,
  },
  '18:54': {
    explanation: `।।18.54।।वह ब्रह्मभूत-अवस्थाको प्राप्त प्रसन्न मनवाला साधक न तो किसीके लिये शोक करता है और न किसीकी इच्छा करता है। ऐसा सम्पूर्ण प्राणियोंमें समभाववाला साधक मेरी पराभक्तिको प्राप्त हो जाता है।`,
  },
  '18:55': {
    explanation: `।।18.55।।उस पराभक्तिसे मेरेको, मैं जितना हूँ और जो हूँ -- इसको तत्त्वसे जान लेता है तथा मेरेको तत्त्वसे जानकर फिर तत्काल मेरेमें प्रविष्ट हो जाता है।`,
  },
  '18:56': {
    explanation: `।।18.56।।मेरा आश्रय लेनेवाला भक्त सदा सब कर्म करता हुआ भी मेरी कृपासे शाश्वत अविनाशी पदको प्राप्त हो जाता है।`,
  },
  '18:57': {
    explanation: `।।18.57।।चित्तसे सम्पूर्ण कर्म मुझमें अर्पण करके, मेरे परायण होकर तथा समताका आश्रय लेकर निरन्तर मुझमें चित्तवाला हो जा।`,
  },
  '18:58': {
    explanation: `।।18.58।।मेरेमें चित्तवाला होकर तू मेरी कृपासे सम्पूर्ण विघ्नोंको तर जायगा और यदि तू अहंकारके कारण मेरी बात नहीं सुनेगा तो तेरा पतन हो जायगा।`,
  },
  '18:59': {
    explanation: `।।18.59।।अहंकारका आश्रय लेकर तू जो ऐसा मान रहा है कि मैं युद्ध नहीं करूँगा, तेरा यह निश्चय मिथ्या (झूठा) है; क्योंकि तेरी क्षात्र-प्रकृति तेरेको युद्धमें लगा देगी।`,
  },
  '18:60': {
    explanation: `।।18.60।।हे कुन्तीनन्दन ! अपने स्वभावजन्य कर्मसे बँधा हुआ तू मोहके कारण जो नहीं करना चाहता, उसको तू (क्षात्र-प्रकृतिके) परवश होकर करेगा।`,
  },
  '18:61': {
    explanation: `।।18.61।।हे अर्जुन ! ईश्वर सम्पूर्ण प्राणियोंके हृदयमें रहता है और अपनी मायासे शरीररूपी यन्त्रपर आरूढ़ हुए सम्पूर्ण प्राणियोंको (उनके स्वभावके अनुसार) भ्रमण कराता रहता है।`,
  },
  '18:62': {
    explanation: `।।18.62।।हे भरतवंशोद्भव अर्जुन ! तू सर्वभावसे उस ईश्वरकी ही शरणमें चला जा। उसकी कृपासे तू परमशान्ति-(संसारसे सर्वथा उपरति-) को और अविनाशी परमपदको प्राप्त हो जायगा।`,
  },
  '18:63': {
    explanation: `।।18.63।।यह गुह्यसे भी गुह्यतर (शरणागतिरूप) ज्ञान मैंने तुझे कह दिया। अब तू इसपर अच्छी तरहसे विचार करके जैसा चाहता है, वैसा कर।`,
  },
  '18:64': {
    explanation: `।।18.64।।सबसे अत्यन्त गोपनीय वचन तू फिर मेरेसे सुन। तू मेरा अत्यन्त प्रिय है, इसलिये मैं तेरे हितकी बात कहूँगा।`,
  },
  '18:65': {
    explanation: `।।18.65।।तू मेरा भक्त हो जा, मेरेमें मनवाला हो जा, मेरा पूजन करनेवाला हो जा और मेरेको नमस्कार कर। ऐसा करनेसे तू मेरेको ही प्राप्त हो जायगा -- यह मैं तेरे सामने सत्य प्रतिज्ञा करता हूँ; क्योंकि तू मेरा अत्यन्त प्रिय है।`,
  },
  '18:67': {
    explanation: `।।18.67।।यह सर्वगुह्यतम वचन अतपस्वीको मत कहना; अभक्तको कभी मत कहना; जो सुनना नहीं चाहता, उसको मत कहना; और जो मेरेमें दोषदृष्टि करता है, उससे भी मत कहना।`,
  },
  '18:68': {
    explanation: `।।18.68।।मेरेमें पराभक्ति करके जो इस परम गोपनीय संवाद-(गीता-ग्रन्थ) को मेरे भक्तोंमें कहेगा, वह मुझे ही प्राप्त होगा -- इसमें कोई सन्देह नहीं है।`,
  },
  '18:69': {
    explanation: `।।18.69।।उसके समान मेरा अत्यन्त प्रिय कार्य करनेवाला मनुष्योंमें कोई भी नहीं है और इस भूमण्डलपर उसके समान मेरा दूसरा कोई प्रियतर होगा भी नहीं।`,
  },
  '18:70': {
    explanation: `।।18.70।।जो मनुष्य हम दोनोंके इस धर्ममय संवादका अध्ययन करेगा, उसके द्वारा भी मैं ज्ञानयज्ञसे पूजित होऊँगा -- ऐसा मेरा मत है।`,
  },
  '18:71': {
    explanation: `।।18.71।।श्रद्धावान् और दोषदृष्टिसे रहित जो मनुष्य इस गीता-ग्रन्थको सुन भी लेगा, वह भी सम्पूर्ण पापोंसे मुक्त होकर पुण्यकारियोंके शुभ लोकोंको प्राप्त हो जायगा।`,
  },
  '18:72': {
    explanation: `।।18.72।।हे पृथानन्दन ! क्या तुमने एकाग्र-चित्तसे इसको सुना ?और हे धनञ्जय ! क्या तुम्हारा अज्ञानसे उत्पन्न मोह नष्ट हुआ ?`,
  },
  '18:73': {
    explanation: `।।18.73।।अर्जुन बोले -- हे अच्युत ! आपकी कृपासे मेरा मोह नष्ट हो गया है और स्मृति प्राप्त हो गयी है। मैं सन्देहरहित होकर स्थित हूँ। अब मैं आपकी आज्ञाका पालन करूँगा।`,
  },
  '18:74': {
    explanation: `।।18.74।।सञ्जय बोले -- इस प्रकार मैंने भगवान् वासुदेव और महात्मा पृथानन्दन अर्जुनका यह रोमाञ्चित करनेवाला अद्भुत संवाद सुना।`,
  },
  '18:75': {
    explanation: `।।18.75।।व्यासजीकी कृपासे मैंने स्वयं इस परम गोपनीय योग (गीता-ग्रन्थ) को कहते हुए साक्षात् योगेश्वर भगवान् श्रीकृष्णसे सुना है।`,
  },
  '18:76': {
    explanation: `।।18.76।।हे राजन् ! भगवान् श्रीकृष्ण और अर्जुनके इस पवित्र और अद्भुत संवादको याद कर-करके मैं बार-बार हर्षित हो रहा हूँ।`,
  },
  '18:77': {
    explanation: `।।18.77।।हे राजन् ! भगवान् श्रीकृष्णके उस अत्यन्त अद्भुत विराट्रूपको याद कर-करके मेरेको बड़ा भारी आश्चर्य हो रहा है और मैं बार-बार हर्षित हो रहा हूँ।`,
  },
};
